//! A minimal DOM for JetBrains settings files.
//!
//! Child order is preserved because some JetBrains elements (`<list>`, ordered
//! `<filter>` chains) are order-sensitive. Attributes are held in a `BTreeMap`,
//! so serialization is canonical without reordering anything that carries
//! meaning. JetBrains already writes components and options alphabetically, so
//! preserving document order still yields stable, machine-independent files.

use std::{collections::BTreeMap, fmt::Write as _};

/// Attributes JetBrains uses to identify a sibling, most specific first. A
/// child carrying one of these is addressed by its value rather than by
/// position, so a projected path survives siblings being inserted or removed.
pub const KEY_ATTRIBUTES: [&str; 9] = [
    "name", "key", "id", "class", "type", "language", "scheme", "ext", "pattern",
];

/// Elements whose identifying attribute is only an address, never the setting
/// itself. Everything else is assumed to mean something by existing.
pub const WRAPPER_ELEMENTS: [&str; 5] = ["option", "entry", "map", "list", "set"];

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Element {
    pub name: String,
    pub attributes: BTreeMap<String, String>,
    pub children: Vec<Element>,
    /// Trimmed character data. JetBrains settings files never mix text and
    /// element children, so a single optional string is sufficient.
    pub text: Option<String>,
}

#[derive(Debug)]
pub struct ParseError(pub String);

impl std::fmt::Display for ParseError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}

impl std::error::Error for ParseError {}

impl Element {
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            ..Self::default()
        }
    }

    /// The identifying attribute for this element, if it carries one.
    pub fn key_attribute(&self) -> Option<(&str, &str)> {
        KEY_ATTRIBUTES.iter().find_map(|attribute| {
            self.attributes
                .get(*attribute)
                .map(|value| (*attribute, value.as_str()))
        })
    }

    /// True when the element carries no value of its own, and can therefore be
    /// pruned once a merge or a prune rule removed its last leaf.
    ///
    /// The distinction that matters: in a *wrapper* element the name is only an
    /// address and the value lives in a sibling attribute, so `<option
    /// name="map" />` with an emptied map holds nothing. In a domain element
    /// the name is the payload — `<global_color_scheme name="Islands Dark" />`
    /// *is* the colour-scheme setting — so it must survive. Anything with
    /// children, text, or an attribute beyond its own address is kept either
    /// way.
    pub fn is_valueless(&self) -> bool {
        if !self.children.is_empty() || self.text.is_some() {
            return false;
        }
        if self.attributes.is_empty() {
            // A bare <map />, <list /> or <set />: pure structure.
            return true;
        }
        WRAPPER_ELEMENTS.contains(&self.name.as_str())
            && self
                .attributes
                .keys()
                .all(|key| KEY_ATTRIBUTES.contains(&key.as_str()))
    }

    /// A shallow copy used when a merge needs to graft a donor path onto a
    /// tree that does not have those ancestors yet.
    #[must_use]
    pub fn shell(&self) -> Self {
        Self {
            name: self.name.clone(),
            attributes: self.attributes.clone(),
            children: Vec::new(),
            text: None,
        }
    }
}

pub fn parse(contents: &str) -> Result<Element, ParseError> {
    let parsed = xmltree::Element::parse(contents.as_bytes())
        .map_err(|error| ParseError(error.to_string()))?;
    Ok(convert(&parsed))
}

fn convert(source: &xmltree::Element) -> Element {
    let mut text = String::new();
    let mut children = Vec::new();
    for node in &source.children {
        match node {
            xmltree::XMLNode::Element(child) => children.push(convert(child)),
            xmltree::XMLNode::Text(chunk) | xmltree::XMLNode::CData(chunk) => text.push_str(chunk),
            _ => {}
        }
    }
    let trimmed = text.trim();
    Element {
        name: source.name.clone(),
        attributes: source
            .attributes
            .iter()
            .map(|(key, value)| (key.clone(), value.clone()))
            .collect(),
        children,
        text: (!trimmed.is_empty()).then(|| trimmed.to_string()),
    }
}

/// Serializes to the same dialect JetBrains itself writes: a single-quoted
/// declaration, two-space indentation, and a space before every `/>`.
pub fn serialize(root: &Element) -> String {
    let mut output = String::from("<?xml version='1.0' encoding='utf-8'?>\n");
    write_element(&mut output, root, 0);
    output
}

fn write_element(output: &mut String, element: &Element, depth: usize) {
    let indent = "  ".repeat(depth);
    let _ = write!(output, "{indent}<{}", element.name);
    for (key, value) in &element.attributes {
        let _ = write!(output, " {key}=\"{}\"", escape_attribute(value));
    }

    if element.children.is_empty() && element.text.is_none() {
        output.push_str(" />\n");
        return;
    }

    output.push('>');
    if let Some(text) = &element.text
        && element.children.is_empty()
    {
        let _ = writeln!(output, "{}</{}>", escape_text(text), element.name);
        return;
    }

    output.push('\n');
    for child in &element.children {
        write_element(output, child, depth + 1);
    }
    let _ = writeln!(output, "{indent}</{}>", element.name);
}

fn escape_attribute(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            // Whitespace inside an attribute is normalized to a space by any
            // conforming parser, so it must survive as a character reference.
            '\n' => escaped.push_str("&#10;"),
            '\r' => escaped.push_str("&#13;"),
            '\t' => escaped.push_str("&#9;"),
            other => escaped.push(other),
        }
    }
    escaped
}

fn escape_text(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            other => escaped.push(other),
        }
    }
    escaped
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips_a_typical_options_file() {
        let source = "<?xml version='1.0' encoding='utf-8'?>\n<application>\n  <component name=\"GeneralSettings\">\n    <option name=\"reopenLastProject\" value=\"false\" />\n  </component>\n</application>";
        let parsed = parse(source).unwrap();
        let serialized = serialize(&parsed);
        assert_eq!(parse(&serialized).unwrap(), parsed);
        assert!(serialized.contains("<option name=\"reopenLastProject\" value=\"false\" />"));
    }

    #[test]
    fn attributes_serialize_in_sorted_order() {
        let parsed = parse("<root b=\"2\" a=\"1\" c=\"3\" />").unwrap();
        assert!(serialize(&parsed).contains("<root a=\"1\" b=\"2\" c=\"3\" />"));
    }

    #[test]
    fn preserves_child_order() {
        let parsed = parse("<list><item value=\"z\" /><item value=\"a\" /></list>").unwrap();
        let serialized = serialize(&parsed);
        let first = serialized.find("\"z\"").unwrap();
        let second = serialized.find("\"a\"").unwrap();
        assert!(first < second, "ordered children must not be sorted");
    }

    #[test]
    fn escapes_significant_whitespace_in_attributes() {
        let parsed = parse("<root value=\"a&#10;b\" />").unwrap();
        let serialized = serialize(&parsed);
        assert!(serialized.contains("&#10;"));
        assert_eq!(parse(&serialized).unwrap(), parsed);
    }

    #[test]
    fn keeps_element_text() {
        let parsed = parse("<place>Java: comments</place>").unwrap();
        assert_eq!(parsed.text.as_deref(), Some("Java: comments"));
        assert_eq!(parse(&serialize(&parsed)).unwrap(), parsed);
    }

    #[test]
    fn a_domain_element_named_by_its_value_is_not_valueless() {
        // The colour scheme setting *is* the name on this element.
        let parsed = parse(r#"<global_color_scheme name="Islands Dark" />"#).unwrap();
        assert!(!parsed.is_valueless());
    }

    #[test]
    fn an_emptied_wrapper_is_valueless() {
        let parsed = parse(r#"<option name="map" />"#).unwrap();
        assert!(parsed.is_valueless());
        assert!(parse("<map />").unwrap().is_valueless());
        assert!(parse(r#"<entry key="a" />"#).unwrap().is_valueless());
    }

    #[test]
    fn a_wrapper_holding_a_value_survives() {
        let parsed = parse(r#"<option name="tabs" value="4" />"#).unwrap();
        assert!(!parsed.is_valueless());
    }

    #[test]
    fn key_attribute_prefers_name() {
        let parsed = parse("<component name=\"A\" id=\"B\" />").unwrap();
        assert_eq!(parsed.key_attribute(), Some(("name", "A")));
    }
}
//! A flat, stable projection of a settings document.
//!
//! Every leaf (an attribute value, or an element's text) gets an address built
//! from its ancestors. Two documents can then be compared, and merged, one
//! setting at a time instead of one file at a time. The projection is a view:
//! the XML tree remains the source of truth, and merged leaves are written
//! back into a real tree so nothing outside the changed setting is disturbed.
//!
//! Address grammar, `/`-separated:
//!   `tag[attr=value]`  element identified by its key attribute
//!   `tag#n`            the n-th sibling sharing `tag`, when it has no key
//!   `@attr`            terminal: an attribute value
//!   `#text`            terminal: character data

use std::collections::BTreeMap;

use super::dom::Element;

/// Leaf address to value. Ordered, so serialization and reports are stable.
pub type Projection = BTreeMap<String, String>;

const TEXT_LEAF: &str = "#text";

/// What JetBrains wraps *Settings for New Projects* in, inside
/// `options/project.default.xml`.
const DEFAULT_PROJECT_PREFIX: &str = "component[name=ProjectManager]/defaultProject#0/";

/// The address of `element` relative to its parent. `same_tag_index` is the
/// element's position among siblings that share its tag name.
fn segment(element: &Element, same_tag_index: usize) -> String {
    element.key_attribute().map_or_else(
        || format!("{}#{same_tag_index}", element.name),
        |(attribute, value)| format!("{}[{attribute}={value}]", element.name),
    )
}

/// Addresses of every child, paired with its index, in document order.
fn child_segments(parent: &Element) -> Vec<(usize, String)> {
    let mut counters: BTreeMap<&str, usize> = BTreeMap::new();
    parent
        .children
        .iter()
        .enumerate()
        .map(|(index, child)| {
            let counter = counters.entry(child.name.as_str()).or_default();
            let address = segment(child, *counter);
            *counter += 1;
            (index, address)
        })
        .collect()
}

/// Flattens `root` into leaf addresses. The root's own tag is not part of any
/// address: a document is only ever compared against the same file from
/// another machine, so the root is shared context rather than information.
pub fn project(root: &Element) -> Projection {
    let mut flattened = Projection::new();
    collect(root, "", &mut flattened);
    flattened
}

fn collect(element: &Element, prefix: &str, output: &mut Projection) {
    let join = |leaf: &str| {
        if prefix.is_empty() {
            leaf.to_string()
        } else {
            format!("{prefix}/{leaf}")
        }
    };

    // The key attribute is already encoded in this element's own address, so
    // emitting it again would only add noise to every diff.
    let key = element.key_attribute().map(|(attribute, _)| attribute);
    for (attribute, value) in &element.attributes {
        if Some(attribute.as_str()) != key {
            output.insert(join(&format!("@{attribute}")), value.clone());
        }
    }
    if let Some(text) = &element.text {
        output.insert(join(TEXT_LEAF), text.clone());
    }
    for (index, address) in child_segments(element) {
        collect(&element.children[index], &join(&address), output);
    }
}

/// Rewrites an address for display, collapsing JetBrains' boilerplate so a
/// report reads like the settings UI rather than like XPath.
///
/// `component[name=Editor]/option[name=Font]/map#0/entry[key=size]/@value`
/// becomes `Editor/Font/size`.
pub fn sugar(path: &str) -> String {
    // Every setting in `project.default.xml` carries the same two segments in
    // front of it. Naming the wrapper once reads better in a report than
    // repeating `ProjectManager/defaultProject` on every line.
    let (path, mut parts) = match path.strip_prefix(DEFAULT_PROJECT_PREFIX) {
        Some(rest) => (rest, vec!["New Projects".to_string()]),
        None => (path, Vec::new()),
    };
    for raw in path.split('/') {
        if matches!(raw, "map#0" | "list#0" | "set#0" | "value#0") {
            continue;
        }
        let simplified = strip_wrapper(raw, "component", "name")
            .or_else(|| strip_wrapper(raw, "option", "name"))
            .or_else(|| strip_wrapper(raw, "entry", "key"));
        match simplified {
            Some(value) => parts.push(value),
            None if raw == "@value" => {}
            // `@themeId` is the setting's name to a reader; the `@` only tells
            // the merge that it addresses an attribute.
            None if raw.starts_with('@') => parts.push(raw[1..].to_string()),
            // `laf#0` is the first and usually only `laf` element. The index
            // matters to the merge and means nothing to a reader, so keep it
            // only where it actually distinguishes siblings.
            None => parts.push(raw.strip_suffix("#0").unwrap_or(raw).to_string()),
        }
    }
    if parts.is_empty() {
        path.to_string()
    } else {
        parts.join("/")
    }
}

fn strip_wrapper(segment: &str, tag: &str, attribute: &str) -> Option<String> {
    segment
        .strip_prefix(&format!("{tag}[{attribute}="))?
        .strip_suffix(']')
        .map(str::to_string)
}

/// Writes `value` at `path`, creating any missing ancestors by copying their
/// shells from `donor` (the tree the leaf is coming from). Returns false when
/// `donor` does not actually contain the path, which would leave the target in
/// a half-built state.
pub fn set_leaf(target: &mut Element, donor: &Element, path: &str, value: &str) -> bool {
    let mut segments = address_segments(path);
    let Some(leaf) = segments.pop() else {
        return false;
    };

    let mut cursor = target;
    let mut source = donor;
    for wanted in segments {
        let Some(donor_index) = find_child(source, wanted) else {
            return false;
        };
        source = &source.children[donor_index];
        if let Some(index) = find_child(cursor, wanted) {
            cursor = &mut cursor.children[index];
        } else {
            cursor.children.push(source.shell());
            let last = cursor.children.len() - 1;
            cursor = &mut cursor.children[last];
        }
    }

    if leaf == TEXT_LEAF {
        cursor.text = Some(value.to_string());
    } else if let Some(attribute) = leaf.strip_prefix('@') {
        cursor
            .attributes
            .insert(attribute.to_string(), value.to_string());
    } else {
        return false;
    }
    true
}

/// Copies everything in `donor` into `target`, creating what is missing and
/// leaving anything `donor` does not mention alone.
///
/// This is the whole-file counterpart to [`set_leaf`], and it deliberately
/// walks the tree rather than replaying [`project`]. Two things are lost in a
/// flattened form. An element whose key attribute *is* the setting —
/// `<global_color_scheme name="Islands Dark" />` — contributes no leaf at all,
/// because the key is already spent addressing it, so replaying leaves would
/// never create it. And addresses are ordered lexically, which puts `laf#10`
/// before `laf#2`, so rebuilding a keyless list from them would number its
/// entries in the wrong order. Walking the donor keeps both.
pub fn graft(target: &mut Element, donor: &Element) {
    for (attribute, value) in &donor.attributes {
        target.attributes.insert(attribute.clone(), value.clone());
    }
    if donor.text.is_some() {
        target.text.clone_from(&donor.text);
    }
    // Document order, so a keyless child lands at the index its address names:
    // `laf#1` is only findable once `laf#0` is there.
    for (index, address) in child_segments(donor) {
        let child = &donor.children[index];
        match find_child(target, &address) {
            Some(existing) => graft(&mut target.children[existing], child),
            None => target.children.push(child.clone()),
        }
    }
}

/// Removes the leaf at `path`, then drops any ancestor left with nothing to
/// serialize.
pub fn remove_leaf(target: &mut Element, path: &str) {
    let mut segments = address_segments(path);
    let Some(leaf) = segments.pop() else {
        return;
    };

    let mut cursor = &mut *target;
    for wanted in &segments {
        match find_child(cursor, wanted) {
            Some(index) => cursor = &mut cursor.children[index],
            None => return,
        }
    }
    if leaf == TEXT_LEAF {
        cursor.text = None;
    } else if let Some(attribute) = leaf.strip_prefix('@') {
        cursor.attributes.remove(attribute);
    }
    prune_empty(target);
}

/// Splits an address without mistaking separators inside a key value for path
/// separators. Rider-backed settings use names such as
/// `option[name=/Default/PatternsAndTemplates/...]/@value`; a plain `split('/')`
/// cannot navigate those leaves and turns every attempted write-back into a
/// no-op.
fn address_segments(path: &str) -> Vec<&str> {
    let mut segments = Vec::new();
    let mut start = 0;
    let mut inside_key = false;
    for (index, character) in path.char_indices() {
        match character {
            '[' if !inside_key => inside_key = true,
            ']' if inside_key => {
                let remainder = &path[index + character.len_utf8()..];
                if remainder.is_empty() || remainder.starts_with('/') {
                    inside_key = false;
                }
            }
            '/' if !inside_key => {
                segments.push(&path[start..index]);
                start = index + character.len_utf8();
            }
            _ => {}
        }
    }
    segments.push(&path[start..]);
    segments
}

/// Drops elements that no longer carry any value. A parent is only removed
/// once all of its children have been, so pruning is bottom-up.
pub fn prune_empty(element: &mut Element) {
    for child in &mut element.children {
        prune_empty(child);
    }
    element.children.retain(|child| !child.is_valueless());
}

fn find_child(parent: &Element, wanted: &str) -> Option<usize> {
    child_segments(parent)
        .into_iter()
        .find(|(_, address)| address == wanted)
        .map(|(index, _)| index)
}

#[cfg(test)]
mod tests {
    use std::fmt::Write as _;

    use super::{super::dom::parse, *};

    fn document() -> Element {
        parse(
            r#"<application>
                 <component name="GeneralSettings">
                   <option name="reopenLastProject" value="false" />
                 </component>
                 <component name="Registry">
                   <entry key="ide.experimental.ui" value="true" source="SYSTEM" />
                 </component>
               </application>"#,
        )
        .unwrap()
    }

    #[test]
    fn projects_each_setting_to_one_address() {
        let flattened = project(&document());
        assert_eq!(
            flattened
                .get("component[name=GeneralSettings]/option[name=reopenLastProject]/@value")
                .map(String::as_str),
            Some("false")
        );
        assert_eq!(
            flattened
                .get("component[name=Registry]/entry[key=ide.experimental.ui]/@source")
                .map(String::as_str),
            Some("SYSTEM")
        );
    }

    #[test]
    fn key_attribute_is_not_repeated_as_a_leaf() {
        let flattened = project(&document());
        assert!(
            !flattened
                .keys()
                .any(|path| path.ends_with("@name") || path.ends_with("@key"))
        );
    }

    #[test]
    fn sugar_reads_like_the_settings_ui() {
        assert_eq!(
            sugar("component[name=GeneralSettings]/option[name=reopenLastProject]/@value"),
            "GeneralSettings/reopenLastProject"
        );
        assert_eq!(
            sugar("component[name=Editor]/option[name=fonts]/map#0/entry[key=size]/@value"),
            "Editor/fonts/size"
        );
        // A non-`value` attribute is the setting's name to a reader, so the
        // `@` that tells the merge it addresses an attribute is dropped.
        assert_eq!(
            sugar("component[name=Registry]/entry[key=ide.ui]/@source"),
            "Registry/ide.ui/source"
        );
        // `#0` means "the first one"; it only earns its place when there is a
        // sibling to distinguish it from.
        assert_eq!(
            sugar("component[name=LafManager]/laf#0/@themeId"),
            "LafManager/laf/themeId"
        );
        assert_eq!(
            sugar("component[name=LafManager]/laf#1/@themeId"),
            "LafManager/laf#1/themeId"
        );
        // Everything in project.default.xml sits under the same two segments,
        // which name the *place* rather than the setting.
        assert_eq!(
            sugar(
                "component[name=ProjectManager]/defaultProject#0/component[name=TypeScriptCompiler]/option[name=memoryAutoIncrease]/@value"
            ),
            "New Projects/TypeScriptCompiler/memoryAutoIncrease"
        );
    }

    #[test]
    fn positional_addresses_disambiguate_keyless_siblings() {
        let parsed = parse(r#"<root><laf themeId="a" /><laf themeId="b" /></root>"#).unwrap();
        let flattened = project(&parsed);
        assert_eq!(
            flattened.get("laf#0/@themeId").map(String::as_str),
            Some("a")
        );
        assert_eq!(
            flattened.get("laf#1/@themeId").map(String::as_str),
            Some("b")
        );
    }

    #[test]
    fn set_leaf_creates_missing_ancestors_from_the_donor() {
        let donor = document();
        let mut target = parse("<application />").unwrap();
        let path = "component[name=GeneralSettings]/option[name=reopenLastProject]/@value";
        assert!(set_leaf(&mut target, &donor, path, "true"));
        assert_eq!(project(&target).get(path).map(String::as_str), Some("true"));
        // Only the requested leaf is grafted, not the donor's other components.
        assert_eq!(target.children.len(), 1);
    }

    #[test]
    fn set_leaf_refuses_paths_the_donor_lacks() {
        let donor = parse("<application />").unwrap();
        let mut target = parse("<application />").unwrap();
        assert!(!set_leaf(
            &mut target,
            &donor,
            "component[name=Nope]/@value",
            "x"
        ));
        assert!(target.children.is_empty());
    }

    #[test]
    fn remove_leaf_prunes_elements_it_empties() {
        let mut target = document();
        remove_leaf(
            &mut target,
            "component[name=GeneralSettings]/option[name=reopenLastProject]/@value",
        );
        let flattened = project(&target);
        assert!(
            !flattened
                .keys()
                .any(|path| path.contains("GeneralSettings"))
        );
        assert!(flattened.keys().any(|path| path.contains("Registry")));
    }

    #[test]
    fn leaf_operations_handle_slashes_inside_key_attributes() {
        let donor = parse(
            r#"<application>
                 <component name="BackendCodeEditorApplicationSettings">
                   <option name="/Default/PatternsAndTemplates/LiveTemplates/Template/=abc/@KeyIndexDefined" type="bool" value="true" />
                 </component>
               </application>"#,
        )
        .unwrap();
        let path = project(&donor)
            .into_keys()
            .find(|path| path.ends_with("/@value"))
            .expect("the option value is projected");

        let mut target = parse("<application />").unwrap();
        assert!(set_leaf(&mut target, &donor, &path, "false"));
        assert_eq!(
            project(&target).get(&path).map(String::as_str),
            Some("false")
        );

        remove_leaf(&mut target, &path);
        assert!(
            !project(&target).contains_key(&path),
            "the addressed value should actually be removed"
        );
    }

    /// The failure a flattened replay would have: this element carries no leaf
    /// at all, because its key attribute is the setting rather than an address.
    #[test]
    fn graft_creates_elements_that_project_to_nothing() {
        let donor =
            parse(r#"<application><global_color_scheme name="Islands Dark" /></application>"#)
                .unwrap();
        assert!(project(&donor).is_empty(), "the premise: nothing to replay");

        let mut target = parse("<application />").unwrap();
        graft(&mut target, &donor);
        assert_eq!(target, donor);
    }

    /// Addresses sort lexically, so `laf#10` precedes `laf#2`. Rebuilding from
    /// them would put the tenth entry second; walking the donor does not.
    #[test]
    fn graft_keeps_the_order_of_keyless_siblings() {
        let mut body = String::new();
        for index in 0..11 {
            let _ = write!(body, r#"<laf themeId="t{index}" />"#);
        }
        let donor = parse(&format!("<application>{body}</application>")).unwrap();

        let mut target = parse("<application />").unwrap();
        graft(&mut target, &donor);

        let themes: Vec<&str> = target
            .children
            .iter()
            .filter_map(|child| child.attributes.get("themeId").map(String::as_str))
            .collect();
        assert_eq!(
            themes,
            [
                "t0", "t1", "t2", "t3", "t4", "t5", "t6", "t7", "t8", "t9", "t10"
            ]
        );
    }

    /// A graft delivers the donor without evicting what the target already had,
    /// which is the whole reason it is not just an overwrite.
    #[test]
    fn graft_leaves_content_the_donor_does_not_mention() {
        let donor = document();
        let mut target =
            parse(r#"<application><component name="Local"><option name="a" value="1" /></component></application>"#)
                .unwrap();
        graft(&mut target, &donor);

        let flattened = project(&target);
        assert_eq!(
            flattened
                .get("component[name=Local]/option[name=a]/@value")
                .map(String::as_str),
            Some("1"),
            "the target's own content survives"
        );
        assert!(
            flattened
                .keys()
                .any(|path| path.contains("GeneralSettings")),
            "and the donor's arrives"
        );
    }

    #[test]
    fn projection_survives_a_serialization_round_trip() {
        let original = document();
        let reparsed = parse(&super::super::dom::serialize(&original)).unwrap();
        assert_eq!(project(&original), project(&reparsed));
    }
}
//! Three-way merge, one setting at a time.
//!
//! Every merge answers the same question for three inputs — the last state
//! both sides agreed on (`base`), what this machine has now (`local`), and what
//! the other side has now (`remote`):
//!
//!   * both sides agree            -> take it, nothing happened
//!   * only `remote` moved         -> take `remote`, report it as incoming
//!   * only `local` moved          -> take `local`, report it as outgoing
//!   * both moved, differently     -> a conflict, resolved by policy
//!
//! Doing this on the *projection* rather than on file text is what makes two
//! IDEs editing different settings in the same file a non-event. Git's line
//! merge would call that a conflict, and its output would not always be
//! well-formed XML.

use crate::{
    settings::roamable::is_tombstone,
    xml::{dom, project},
};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Side {
    Local,
    Remote,
}

/// What to do when both sides changed the same setting.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ConflictPolicy {
    /// The machine running the sync wins. Predictable, and it means the
    /// settings you can see in front of you are the ones that survive.
    #[default]
    PreferLocal,
    PreferRemote,
    /// Refuse to merge, leaving both sides untouched.
    Fail,
}

impl ConflictPolicy {
    fn winner(self) -> Option<Side> {
        match self {
            Self::PreferLocal => Some(Side::Local),
            Self::PreferRemote => Some(Side::Remote),
            Self::Fail => None,
        }
    }
}

/// A single setting changing value. `None` means the setting is absent, which
/// for JetBrains means "left at its default".
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Change {
    /// Raw projection address, used to apply the change to a real document.
    /// Empty when the change is about the file as a whole.
    pub path: String,
    /// The same address rewritten for people to read.
    pub setting: String,
    pub from: Option<String>,
    pub to: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Conflict {
    pub setting: String,
    pub local: Option<String>,
    pub remote: Option<String>,
    pub resolved_to: Option<Side>,
}

#[derive(Debug, Clone, Default)]
pub struct FileMerge {
    /// Merged bytes, or `None` when the file should not exist.
    pub content: Option<Vec<u8>>,
    /// Settings this machine is taking from the other side.
    pub incoming: Vec<Change>,
    /// Settings this machine is contributing.
    pub outgoing: Vec<Change>,
    pub conflicts: Vec<Conflict>,
}

impl FileMerge {
    pub fn is_noop(&self) -> bool {
        self.incoming.is_empty() && self.outgoing.is_empty() && self.conflicts.is_empty()
    }
}

fn as_text(bytes: Option<&[u8]>) -> Option<&str> {
    bytes.and_then(|raw| std::str::from_utf8(raw).ok())
}

/// A `DELETED` tombstone means the same thing as an absent file.
fn normalize(bytes: Option<&[u8]>) -> Option<&[u8]> {
    match as_text(bytes) {
        Some(text) if is_tombstone(text) => None,
        _ => bytes,
    }
}

/// Merges one store file. `label` is only used to decide whether to parse as
/// XML and to describe changes.
pub fn merge_file(
    base: Option<&[u8]>,
    local: Option<&[u8]>,
    remote: Option<&[u8]>,
    policy: ConflictPolicy,
) -> FileMerge {
    let (base, local, remote) = (normalize(base), normalize(local), normalize(remote));

    // Both sides agree; there is nothing to do regardless of the base.
    if local == remote {
        return FileMerge {
            content: local.map(<[u8]>::to_vec),
            ..FileMerge::default()
        };
    }

    // When both sides have the file, always reconcile it entry by entry — even
    // if only one side moved. The three-way logic reaches the same answer as a
    // wholesale copy would, but it can say *which settings* are arriving,
    // which is the whole point of the report.
    if let (Some(local_text), Some(remote_text)) = (as_text(local), as_text(remote)) {
        if let (Ok(local_doc), Ok(remote_doc)) = (dom::parse(local_text), dom::parse(remote_text)) {
            let base_doc = as_text(base).and_then(|text| dom::parse(text).ok());
            return merge_documents(base_doc.as_ref(), &local_doc, &remote_doc, policy);
        }
        return merge_text(as_text(base), local_text, remote_text, policy);
    }

    // One side does not have the file at all, so this is an add or a delete.
    if local == base {
        return whole_file(local, remote, Side::Remote);
    }
    if remote == base {
        return whole_file(remote, local, Side::Local);
    }
    binary_conflict(local, remote, policy)
}

/// One side is unchanged, so the other side's version wins outright.
fn whole_file(unchanged: Option<&[u8]>, moved: Option<&[u8]>, side: Side) -> FileMerge {
    let describe = |value: Option<&[u8]>| {
        value.map(|_| {
            if side == Side::Remote {
                "updated remotely".to_string()
            } else {
                "updated locally".to_string()
            }
        })
    };
    let change = Change {
        path: String::new(),
        setting: match (unchanged.is_some(), moved.is_some()) {
            (true, false) => "(file removed)".to_string(),
            (false, true) => "(file added)".to_string(),
            _ => "(file contents)".to_string(),
        },
        from: describe(unchanged),
        to: describe(moved),
    };
    let mut merge = FileMerge {
        content: moved.map(<[u8]>::to_vec),
        ..FileMerge::default()
    };
    match side {
        Side::Remote => merge.incoming.push(change),
        Side::Local => merge.outgoing.push(change),
    }
    merge
}

/// The real work: reconcile two documents setting by setting.
fn merge_documents(
    base: Option<&dom::Element>,
    local: &dom::Element,
    remote: &dom::Element,
    policy: ConflictPolicy,
) -> FileMerge {
    let base_view = base.map(project::project).unwrap_or_default();
    let local_view = project::project(local);
    let remote_view = project::project(remote);

    let mut merged = local.clone();
    let mut result = FileMerge::default();

    let mut paths: Vec<&String> = local_view.keys().chain(remote_view.keys()).collect();
    paths.sort_unstable();
    paths.dedup();

    for path in paths {
        let in_base = base_view.get(path);
        let in_local = local_view.get(path);
        let in_remote = remote_view.get(path);

        if in_local == in_remote {
            continue;
        }
        let readable = project::sugar(path);

        let take_remote = if in_local == in_base {
            true
        } else if in_remote == in_base {
            false
        } else {
            let winner = policy.winner();
            result.conflicts.push(Conflict {
                setting: readable.clone(),
                local: in_local.cloned(),
                remote: in_remote.cloned(),
                resolved_to: winner,
            });
            match winner {
                Some(side) => side == Side::Remote,
                // Leave the local value in place; the caller aborts anyway.
                None => false,
            }
        };

        if take_remote {
            result.incoming.push(Change {
                path: path.clone(),
                setting: readable,
                from: in_local.cloned(),
                to: in_remote.cloned(),
            });
            match in_remote {
                Some(value) => {
                    project::set_leaf(&mut merged, remote, path, value);
                }
                None => project::remove_leaf(&mut merged, path),
            }
        } else if in_remote != in_local {
            result.outgoing.push(Change {
                path: path.clone(),
                setting: readable,
                from: in_remote.cloned(),
                to: in_local.cloned(),
            });
        }
    }

    project::prune_empty(&mut merged);
    result.content = Some(dom::serialize(&merged).into_bytes());
    result
}

/// Splits a JVM flag into the key two machines could disagree about, so
/// `-Xmx4g` and `-Xmx8g` conflict while `-Xmx4g` and `-XX:+UseZGC` do not.
fn flag_key(line: &str) -> String {
    let trimmed = line.trim();
    if let Some((name, _)) = trimmed.split_once('=') {
        return name.to_string();
    }
    // Size-suffixed flags such as -Xmx4g / -Xms512m.
    let stripped = trimmed.trim_end_matches(['k', 'K', 'm', 'M', 'g', 'G']);
    stripped
        .trim_end_matches(|character: char| character.is_ascii_digit())
        .to_string()
}

/// Line-oriented merge for plain-text settings, chiefly `.vmoptions`.
///
/// Treated as a set of flags: additions from both sides are kept, deletions
/// from either side are honoured, and only two different values for the *same*
/// flag count as a conflict.
fn merge_text(base: Option<&str>, local: &str, remote: &str, policy: ConflictPolicy) -> FileMerge {
    let lines = |text: &str| -> Vec<String> {
        text.lines()
            .map(str::trim_end)
            .filter(|line| !line.is_empty())
            .map(str::to_string)
            .collect()
    };
    let base_lines = base.map(lines).unwrap_or_default();
    let local_lines = lines(local);
    let remote_lines = lines(remote);

    let mut result = FileMerge::default();
    let mut merged: Vec<String> = Vec::new();

    let added = |current: &[String]| -> Vec<String> {
        current
            .iter()
            .filter(|line| !base_lines.contains(line))
            .cloned()
            .collect()
    };
    let local_added = added(&local_lines);
    let remote_added = added(&remote_lines);

    // A base line survives unless one side deliberately removed it.
    for line in &base_lines {
        let kept_locally = local_lines.contains(line);
        let kept_remotely = remote_lines.contains(line);
        if kept_locally && kept_remotely {
            merged.push(line.clone());
            continue;
        }
        let change = Change {
            path: String::new(),
            setting: flag_key(line),
            from: Some(line.clone()),
            to: None,
        };
        if kept_locally {
            result.incoming.push(change);
        } else {
            result.outgoing.push(change);
        }
    }

    // Additions. The same flag carrying different values on the two sides is
    // the only thing that can conflict here.
    for line in &local_added {
        let key = flag_key(line);
        match remote_added.iter().find(|other| flag_key(other) == key) {
            Some(other) if other == line => {
                // Both machines added the identical flag: not a change at all.
                merged.push(line.clone());
            }
            Some(other) => {
                let winner = policy.winner();
                result.conflicts.push(Conflict {
                    setting: key,
                    local: Some(line.clone()),
                    remote: Some(other.clone()),
                    resolved_to: winner,
                });
                merged.push(if winner == Some(Side::Remote) {
                    other.clone()
                } else {
                    line.clone()
                });
            }
            None => {
                merged.push(line.clone());
                result.outgoing.push(Change {
                    path: String::new(),
                    setting: key,
                    from: None,
                    to: Some(line.clone()),
                });
            }
        }
    }
    for line in &remote_added {
        let key = flag_key(line);
        // Anything sharing a key with a local addition was settled above.
        if local_added.iter().any(|other| flag_key(other) == key) {
            continue;
        }
        merged.push(line.clone());
        result.incoming.push(Change {
            path: String::new(),
            setting: key,
            from: None,
            to: Some(line.clone()),
        });
    }

    let mut text = merged.join("\n");
    if !text.is_empty() {
        text.push('\n');
    }
    result.content = Some(text.into_bytes());
    result
}

/// Whole-file three-way merge, for store files that are not IDE settings
/// (`sync.toml`, `plugins.json`). No structural knowledge is applied: the side
/// that moved wins, and if both moved the policy decides.
pub fn merge_opaque(
    base: Option<&[u8]>,
    local: Option<&[u8]>,
    remote: Option<&[u8]>,
    policy: ConflictPolicy,
) -> FileMerge {
    if local == remote {
        return FileMerge {
            content: local.map(<[u8]>::to_vec),
            ..FileMerge::default()
        };
    }
    if local == base {
        return whole_file(local, remote, Side::Remote);
    }
    if remote == base {
        return whole_file(remote, local, Side::Local);
    }
    binary_conflict(local, remote, policy)
}

fn binary_conflict(
    local: Option<&[u8]>,
    remote: Option<&[u8]>,
    policy: ConflictPolicy,
) -> FileMerge {
    let winner = policy.winner();
    let content = match winner {
        Some(Side::Remote) => remote,
        _ => local,
    };
    FileMerge {
        content: content.map(<[u8]>::to_vec),
        conflicts: vec![Conflict {
            setting: "(whole file)".to_string(),
            local: local.map(|_| "local version".to_string()),
            remote: remote.map(|_| "remote version".to_string()),
            resolved_to: winner,
        }],
        ..FileMerge::default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const BASE: &str = r#"<application>
  <component name="Editor">
    <option name="tabs" value="4" />
    <option name="wrap" value="false" />
  </component>
</application>"#;

    fn merge(base: &str, local: &str, remote: &str) -> FileMerge {
        merge_file(
            Some(base.as_bytes()),
            Some(local.as_bytes()),
            Some(remote.as_bytes()),
            ConflictPolicy::PreferLocal,
        )
    }

    fn value_of(merge: &FileMerge, setting: &str) -> Option<String> {
        let text = String::from_utf8(merge.content.clone()?).ok()?;
        let document = dom::parse(&text).ok()?;
        project::project(&document)
            .into_iter()
            .find(|(path, _)| project::sugar(path) == setting)
            .map(|(_, value)| value)
    }

    #[test]
    fn disjoint_edits_in_one_file_both_survive() {
        let local = BASE.replace(r#"name="tabs" value="4""#, r#"name="tabs" value="2""#);
        let remote = BASE.replace(
            r#"name="wrap" value="false""#,
            r#"name="wrap" value="true""#,
        );
        let merged = merge(BASE, &local, &remote);

        assert!(
            merged.conflicts.is_empty(),
            "different settings never clash"
        );
        assert_eq!(value_of(&merged, "Editor/tabs").as_deref(), Some("2"));
        assert_eq!(value_of(&merged, "Editor/wrap").as_deref(), Some("true"));
        assert_eq!(merged.incoming.len(), 1);
        assert_eq!(merged.outgoing.len(), 1);
    }

    #[test]
    fn the_same_setting_changed_twice_is_a_conflict() {
        let local = BASE.replace(r#"name="tabs" value="4""#, r#"name="tabs" value="2""#);
        let remote = BASE.replace(r#"name="tabs" value="4""#, r#"name="tabs" value="8""#);
        let merged = merge(BASE, &local, &remote);

        assert_eq!(merged.conflicts.len(), 1);
        let conflict = &merged.conflicts[0];
        assert_eq!(conflict.setting, "Editor/tabs");
        assert_eq!(conflict.local.as_deref(), Some("2"));
        assert_eq!(conflict.remote.as_deref(), Some("8"));
        assert_eq!(value_of(&merged, "Editor/tabs").as_deref(), Some("2"));
    }

    #[test]
    fn conflict_policy_can_prefer_the_remote_value() {
        let local = BASE.replace(r#"name="tabs" value="4""#, r#"name="tabs" value="2""#);
        let remote = BASE.replace(r#"name="tabs" value="4""#, r#"name="tabs" value="8""#);
        let merged = merge_file(
            Some(BASE.as_bytes()),
            Some(local.as_bytes()),
            Some(remote.as_bytes()),
            ConflictPolicy::PreferRemote,
        );
        assert_eq!(value_of(&merged, "Editor/tabs").as_deref(), Some("8"));
    }

    #[test]
    fn a_setting_added_remotely_arrives() {
        let remote = BASE.replace(
            "</component>",
            r#"  <option name="fontSize" value="14" />
  </component>"#,
        );
        let merged = merge(BASE, BASE, &remote);
        assert_eq!(value_of(&merged, "Editor/fontSize").as_deref(), Some("14"));
        assert_eq!(merged.incoming.len(), 1);
    }

    #[test]
    fn reverting_a_setting_to_its_default_propagates_as_a_removal() {
        let remote = BASE.replace(
            r#"    <option name="wrap" value="false" />
"#,
            "",
        );
        let merged = merge(BASE, BASE, &remote);
        assert_eq!(value_of(&merged, "Editor/wrap"), None);
        assert_eq!(merged.incoming.len(), 1);
        assert_eq!(merged.incoming[0].to, None);
    }

    #[test]
    fn identical_edits_on_both_sides_are_not_a_conflict() {
        let changed = BASE.replace(r#"value="4""#, r#"value="2""#);
        let merged = merge(BASE, &changed, &changed);
        assert!(merged.conflicts.is_empty());
        assert!(merged.is_noop());
    }

    #[test]
    fn a_tombstone_is_treated_as_an_absent_file() {
        let merged = merge_file(
            Some(BASE.as_bytes()),
            Some(b"DELETED"),
            Some(BASE.as_bytes()),
            ConflictPolicy::PreferLocal,
        );
        assert_eq!(
            merged.content, None,
            "local deletion wins over an idle remote"
        );
    }

    #[test]
    fn merged_output_is_always_parseable() {
        let local = BASE.replace(r#"name="tabs" value="4""#, r#"name="tabs" value="2""#);
        let remote = BASE.replace(
            r#"name="wrap" value="false""#,
            r#"name="wrap" value="true""#,
        );
        let merged = merge(BASE, &local, &remote);
        let text = String::from_utf8(merged.content.unwrap()).unwrap();
        assert!(dom::parse(&text).is_ok());
    }

    #[test]
    fn vmoptions_additions_from_both_machines_are_kept() {
        let merged = merge_file(
            Some(b"-Xmx4g\n"),
            Some(b"-Xmx4g\n-XX:+UseZGC\n"),
            Some(b"-Xmx4g\n-Dfile.encoding=UTF-8\n"),
            ConflictPolicy::PreferLocal,
        );
        let text = String::from_utf8(merged.content.unwrap()).unwrap();
        assert!(text.contains("-XX:+UseZGC"));
        assert!(text.contains("-Dfile.encoding=UTF-8"));
        assert!(text.contains("-Xmx4g"));
        assert!(merged.conflicts.is_empty());
    }

    #[test]
    fn the_same_jvm_flag_with_two_values_conflicts() {
        let merged = merge_file(
            Some(b"-Xms512m\n"),
            Some(b"-Xms512m\n-Xmx4g\n"),
            Some(b"-Xms512m\n-Xmx16g\n"),
            ConflictPolicy::PreferLocal,
        );
        assert_eq!(merged.conflicts.len(), 1);
        assert_eq!(merged.conflicts[0].setting, "-Xmx");
        let text = String::from_utf8(merged.content.unwrap()).unwrap();
        assert!(text.contains("-Xmx4g"), "local preference applied");
        assert!(!text.contains("-Xmx16g"));
    }

    #[test]
    fn flag_key_groups_values_of_the_same_option() {
        assert_eq!(flag_key("-Xmx4g"), flag_key("-Xmx16g"));
        assert_eq!(flag_key("-Dfile.encoding=UTF-8"), "-Dfile.encoding");
        assert_ne!(flag_key("-Xmx4g"), flag_key("-Xms4g"));
    }

    #[test]
    fn fail_policy_reports_the_conflict_without_choosing() {
        let local = BASE.replace(r#"value="4""#, r#"value="2""#);
        let remote = BASE.replace(r#"value="4""#, r#"value="8""#);
        let merged = merge_file(
            Some(BASE.as_bytes()),
            Some(local.as_bytes()),
            Some(remote.as_bytes()),
            ConflictPolicy::Fail,
        );
        assert_eq!(merged.conflicts.len(), 1);
        assert_eq!(merged.conflicts[0].resolved_to, None);
    }
}

