use std::path::PathBuf;

use clap::{CommandFactory, Parser, Subcommand, ValueEnum};

use crate::{
    config,
    config::{LocalConfig, PluginRule},
    error::Result,
    paths::Paths,
    plugins,
    progress::Progress,
    style::Style,
    sync::{ConflictPolicy, Engine, SyncOptions, render_with},
};

#[derive(Debug, Parser)]
#[command(
    name = "jbsync",
    version = crate::VERSION,
    about = "Settings and plugin sync for JetBrains IDEs",
    long_about = "jbsync keeps JetBrains IDE settings in step across IDEs and machines.\n\n\
                  It stores only the settings you actually changed, merges them one setting \
                  at a time so two IDEs editing the same file do not collide, and keeps the \
                  sync repository itself out of your way."
)]
pub struct Cli {
    /// Override the jbsync data directory (default: ~/.jbsync).
    #[arg(long, global = true, env = "JBSYNC_CONFIG_DIR")]
    config_dir: Option<PathBuf>,

    /// Also list settings dropped for not being user choices.
    #[arg(long, short, global = true)]
    verbose: bool,

    #[command(subcommand)]
    command: Command,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
enum Prefer {
    /// This machine's value wins a conflict.
    Local,
    /// The incoming value wins a conflict.
    Remote,
    /// Report conflicts and change nothing.
    Neither,
}

impl From<Prefer> for ConflictPolicy {
    fn from(value: Prefer) -> Self {
        match value {
            Prefer::Local => Self::PreferLocal,
            Prefer::Remote => Self::PreferRemote,
            Prefer::Neither => Self::Fail,
        }
    }
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Set up the local configuration and the sync store.
    Init {
        /// Git remote to publish to. Without one the store stays on this machine.
        #[arg(long)]
        remote: Option<String>,
        /// Name for this machine in reports and per-machine overrides.
        #[arg(long)]
        machine: Option<String>,
    },
    /// Show what a sync would do, without changing anything.
    Status,
    /// Reconcile every IDE with the store, and the store with other machines.
    Sync {
        /// Report the plan without writing anything.
        #[arg(long)]
        dry_run: bool,
        /// Who wins when both sides changed the same setting.
        #[arg(long, value_enum, default_value = "local")]
        prefer: Prefer,
        /// Limit to IDEs matching these selectors (name, product, or glob).
        #[arg(long = "ide")]
        ides: Vec<String>,
        /// Gather settings into the store without writing back to the IDEs.
        #[arg(long)]
        collect_only: bool,
        /// Report missing plugins instead of installing them.
        #[arg(long)]
        no_install_plugins: bool,
        /// Accepted and ignored: installing is the default now.
        #[arg(long, hide = true)]
        install_plugins: bool,
        /// Commit message for the git backend.
        #[arg(long, short, default_value = "Sync JetBrains settings")]
        message: String,
    },
    /// List the JetBrains IDEs jbsync can see.
    Ides,
    /// Inspect or change where the store is kept.
    Repo {
        #[command(subcommand)]
        action: RepoAction,
    },
    /// Show the recorded plugins and which IDEs are missing them.
    Plugins {
        #[command(subcommand)]
        action: Option<PluginAction>,
    },
    /// Turn off JetBrains' bundled Backup and Sync so the two do not fight.
    DisableBuiltinSync {
        #[arg(long)]
        dry_run: bool,
    },
    /// Replace the running executable with the requested release.
    Update {
        /// Release to install, e.g. 2026.07.29.2. Defaults to the newest.
        #[arg(long, default_value = "latest")]
        version: String,
        /// Print the result as JSON instead of a sentence.
        #[arg(long)]
        json: bool,
    },
    /// Print a shell completion script.
    Completions {
        #[arg(value_enum)]
        shell: clap_complete::Shell,
    },
}

#[derive(Debug, Subcommand)]
enum RepoAction {
    /// Show the store location and remote.
    Show,
    /// Point the store at a git remote.
    Set {
        /// Remote URL, e.g. git@github.com:you/jetbrains-settings.git
        url: String,
    },
    /// Stop publishing to a remote and keep the store local.
    Unset,
}

#[derive(Debug, Subcommand)]
enum PluginAction {
    /// Install a plugin only into IDEs matching a glob, and nowhere else.
    Only {
        /// Plugin ID from its descriptor, e.g. com.falsepattern.zigbrains
        id: String,
        /// Glob over IDE directory name or product, e.g. "CLion*"
        #[arg(long = "ide")]
        ide: String,
    },
    /// Offer a plugin to matching IDEs even if jbsync judges it incompatible.
    Allow {
        /// Plugin ID from its descriptor.
        id: String,
        /// Glob over IDE directory name or product; every IDE by default.
        #[arg(long = "ide", default_value = "*")]
        ide: String,
    },
    /// Never offer a plugin to matching IDEs.
    Deny {
        /// Plugin ID from its descriptor.
        id: String,
        /// Glob over IDE directory name or product; every IDE by default.
        #[arg(long = "ide", default_value = "*")]
        ide: String,
    },
}

pub fn run() -> anyhow::Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Command::Init { remote, machine } => init(cli.config_dir, remote, machine)?,
        Command::Status => {
            let mut engine = Engine::open(cli.config_dir)?;
            let options = SyncOptions {
                dry_run: true,
                ..SyncOptions::default()
            };
            let report = engine.sync_reporting(&options, &mut Progress::new())?;
            print!("{}", render_with(&report, cli.verbose, Style::auto()));
        }
        Command::Sync {
            dry_run,
            prefer,
            ides,
            collect_only,
            no_install_plugins,
            install_plugins: _,
            message,
        } => {
            let mut engine = Engine::open(cli.config_dir)?;
            let options = SyncOptions {
                dry_run,
                policy: prefer.into(),
                message,
                only: ides,
                collect_only,
                install_plugins: !no_install_plugins,
            };
            let report = engine.sync_reporting(&options, &mut Progress::new())?;
            print!("{}", render_with(&report, cli.verbose, Style::auto()));
        }
        Command::Ides => {
            let engine = Engine::open(cli.config_dir)?;
            if engine.ides.is_empty() {
                println!("No JetBrains IDEs found.");
            }
            for ide in &engine.ides {
                let name = ide
                    .path
                    .file_name()
                    .map(|value| value.to_string_lossy().into_owned())
                    .unwrap_or_default();
                let build = ide.metadata.as_ref().map_or_else(String::new, |metadata| {
                    format!("build {}", metadata.build_number)
                });
                println!("{name:<24}{:<16}{build}", ide.product);
            }
        }
        Command::Repo { action } => repo(cli.config_dir, action)?,
        Command::Plugins {
            action: Some(action),
        } => plugin_rule(cli.config_dir, action)?,
        Command::Plugins { action: None } => {
            let engine = Engine::open(cli.config_dir)?;
            let manifest = plugins::Manifest::load(&engine.store_root().join("plugins.json"))?;
            if manifest.plugins.is_empty() {
                println!("No plugins recorded yet. Run `jbsync sync` first.");
            }
            for plugin in &manifest.plugins {
                println!(
                    "{:<44}{:<12}{}",
                    plugin.id,
                    plugin.version,
                    plugin.source_products.join(", ")
                );
            }
            let selected: Vec<&crate::ide::Ide> = engine.ides.iter().collect();
            for action in plugins::plan_installs(&selected, &manifest, &engine.sync_config) {
                let verb = if action.install { "missing" } else { "skip" };
                println!(
                    "  {}: {verb} {} ({})",
                    action.ide, action.plugin, action.reason
                );
            }

            let broken = plugins::diagnose(&selected, &engine.sync_config);
            if !broken.is_empty() {
                println!("\nInstalled but cannot load:");
                for entry in &broken {
                    println!(
                        "  {}: {} needs {}",
                        entry.ide,
                        entry.plugin,
                        entry.missing.join(", ")
                    );
                    if !entry.installable.is_empty() {
                        println!(
                            "      fix: install {} in {}",
                            entry.installable.join(", "),
                            entry.ide
                        );
                    }
                }
            }
        }
        Command::DisableBuiltinSync { dry_run } => {
            let engine = Engine::open(cli.config_dir)?;
            let actions = engine.disable_builtin_sync(dry_run)?;
            if actions.is_empty() {
                println!("JetBrains Backup and Sync is already off everywhere.");
            }
            for action in actions {
                println!("{action}");
            }
        }
        Command::Update { version, json } => {
            if !json {
                if version == "latest" {
                    eprintln!("Checking for the latest jbsync release...");
                } else {
                    eprintln!("Installing jbsync {version}...");
                }
            }
            let summary = crate::update::update_current(&version, json)?;
            if json {
                println!("{}", serde_json::to_string(&summary)?);
            } else {
                println!("{}", summary.describe("jbsync"));
            }
        }
        Command::Completions { shell } => {
            let mut command = Cli::command();
            let name = command.get_name().to_string();
            clap_complete::generate(shell, &mut command, name, &mut std::io::stdout());
        }
    }
    Ok(())
}

fn init(
    config_dir: Option<PathBuf>,
    remote: Option<String>,
    machine: Option<String>,
) -> Result<()> {
    let paths = Paths::discover(config_dir.clone())?;
    let path = paths.local_config_path();
    let mut local = LocalConfig::load(&path)?;
    if remote.is_some() {
        local.repo.remote = remote;
    }
    if machine.is_some() {
        local.machine.id = machine;
    }
    local.save(&path)?;

    // Opening the engine creates and prepares the store.
    let engine = Engine::open(config_dir)?;
    println!("config  {}", path.display());
    println!("store   {}", engine.store_root().display());
    println!("machine {}", engine.machine);
    println!("found   {} IDE(s)", engine.ides.len());
    println!("\nNext: jbsync status");
    Ok(())
}

fn repo(config_dir: Option<PathBuf>, action: RepoAction) -> Result<()> {
    let paths = Paths::discover(config_dir.clone())?;
    let path = paths.local_config_path();
    let mut local = LocalConfig::load(&path)?;

    match action {
        RepoAction::Show => {
            println!("store   {}", paths.data_dir(&local.repo).display());
            println!("backend {}", local.repo.backend);
            println!(
                "remote  {}",
                local.repo.remote.as_deref().unwrap_or("(local only)")
            );
            println!("branch  {}", local.repo.branch);
        }
        RepoAction::Set { url } => {
            local.repo.remote = Some(url.clone());
            local.save(&path)?;
            Engine::open(config_dir)?;
            println!("Store now publishes to {url}");
        }
        RepoAction::Unset => {
            local.repo.remote = None;
            local.save(&path)?;
            Engine::open(config_dir)?;
            println!("Store is now local only.");
        }
    }
    Ok(())
}

/// Writes one `[[plugins.rule]]` into the store's `sync.toml`, so scoping a
/// plugin does not mean hand-editing TOML.
fn plugin_rule(config_dir: Option<PathBuf>, action: PluginAction) -> Result<()> {
    let engine = Engine::open(config_dir)?;
    let path = engine.store_root().join("sync.toml");
    let rule = match action {
        PluginAction::Only { id, ide } => PluginRule {
            id,
            ide,
            action: "only".to_string(),
        },
        PluginAction::Allow { id, ide } => PluginRule {
            id,
            ide,
            action: "allow".to_string(),
        },
        PluginAction::Deny { id, ide } => PluginRule {
            id,
            ide,
            action: "deny".to_string(),
        },
    };

    match config::append_plugin_rule(&path, &rule)? {
        config::RuleWrite::AlreadyPresent => {
            println!(
                "Already set: {} is {} for {}",
                rule.id, rule.action, rule.ide
            );
            return Ok(());
        }
        config::RuleWrite::Added => {}
    }

    match rule.action.as_str() {
        "only" => println!("{} will be installed only into {}.", rule.id, rule.ide),
        "allow" => println!("{} is now allowed in {}.", rule.id, rule.ide),
        _ => println!("{} will not be installed into {}.", rule.id, rule.ide),
    }
    println!("Written to {}", path.display());
    println!("Run `jbsync sync` to commit it to the store.");
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn command_tree_is_valid() {
        Cli::command().debug_assert();
    }

    /// Reads the effective install decision the way `run` does.
    fn installs(argv: &[&str]) -> bool {
        match Cli::parse_from(argv).command {
            Command::Sync {
                no_install_plugins, ..
            } => !no_install_plugins,
            other => panic!("expected a sync command, got {other:?}"),
        }
    }

    #[test]
    fn plugin_installation_is_opt_out() {
        assert!(installs(&["jbsync", "sync"]), "installing is the default");
        assert!(!installs(&["jbsync", "sync", "--no-install-plugins"]));
    }

    #[test]
    fn the_old_install_plugins_flag_is_still_accepted() {
        // It was the way to ask for this behaviour, and it now describes the
        // default. Scripts carrying it must not start failing.
        assert!(installs(&["jbsync", "sync", "--install-plugins"]));
    }

    #[test]
    fn prefer_maps_onto_the_merge_policy() {
        assert_eq!(
            ConflictPolicy::from(Prefer::Local),
            ConflictPolicy::PreferLocal
        );
        assert_eq!(
            ConflictPolicy::from(Prefer::Remote),
            ConflictPolicy::PreferRemote
        );
        assert_eq!(ConflictPolicy::from(Prefer::Neither), ConflictPolicy::Fail);
    }

    #[test]
    fn sync_defaults_to_writing_and_preferring_local() {
        let cli = Cli::parse_from(["jbsync", "sync"]);
        let Command::Sync {
            dry_run,
            prefer,
            collect_only,
            install_plugins,
            ..
        } = cli.command
        else {
            panic!("expected sync");
        };
        assert!(!dry_run);
        assert!(!collect_only);
        assert!(
            !install_plugins,
            "installing plugins launches the IDE, so it must be opt-in"
        );
        assert_eq!(ConflictPolicy::from(prefer), ConflictPolicy::PreferLocal);
    }

    #[test]
    fn ide_selectors_accumulate() {
        let cli = Cli::parse_from(["jbsync", "sync", "--ide", "PyCharm*", "--ide", "CLion*"]);
        let Command::Sync { ides, .. } = cli.command else {
            panic!("expected sync");
        };
        assert_eq!(ides, vec!["PyCharm*", "CLion*"]);
    }
}
//! Two-tier configuration: a local, unsynced `config.toml` that only knows how
//! to reach the sync-data store and where `JetBrains` lives on this machine, and
//! a `sync.toml` that lives *inside* the sync-data store and therefore
//! replicates to every machine automatically.

use std::{collections::BTreeMap, fmt::Write as _, path::PathBuf};

use serde::{Deserialize, Serialize};

use crate::error::Result;

fn read_toml<T: Default + for<'de> Deserialize<'de>>(path: &std::path::Path) -> Result<T> {
    if !path.exists() {
        return Ok(T::default());
    }
    let contents = std::fs::read_to_string(path)?;
    toml::from_str(&contents).map_err(|error| {
        crate::error::JbsyncError::configuration(format!("{}: {error}", path.display()))
    })
}

fn write_toml<T: Serialize>(path: &std::path::Path, value: &T) -> Result<()> {
    let encoded = toml::to_string_pretty(value)
        .map_err(|error| crate::error::JbsyncError::configuration(error.to_string()))?;
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, encoded)?;
    Ok(())
}

// ---------------------------------------------------------------------------
// Local, machine-specific config: ~/.jbsync/config.toml
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(default)]
pub struct LocalConfig {
    pub repo: RepoConfig,
    pub jetbrains: LocalJetbrainsConfig,
    pub machine: MachineIdentity,
}

impl LocalConfig {
    pub fn load(path: &std::path::Path) -> Result<Self> {
        read_toml(path)
    }

    pub fn save(&self, path: &std::path::Path) -> Result<()> {
        write_toml(path, self)
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct RepoConfig {
    /// Only "git" is implemented today; other values are reserved for future
    /// backends (Convex, Turso, a custom Railway service, ...).
    pub backend: String,
    /// A remote the local bare repo pushes to/pulls from. Left unset, the
    /// sync-data store stays purely local under this machine's data directory.
    pub remote: Option<String>,
    /// Overrides where the local working copy of the sync-data store lives.
    pub path: Option<PathBuf>,
    /// Branch the git backend publishes to.
    pub branch: String,
}

impl Default for RepoConfig {
    fn default() -> Self {
        Self {
            backend: "git".to_string(),
            remote: None,
            path: None,
            branch: "main".to_string(),
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(default)]
pub struct LocalJetbrainsConfig {
    /// "auto" (or unset) detects the OS-conventional `JetBrains` config root.
    pub root: Option<String>,
    pub install_roots: Vec<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(default)]
pub struct MachineIdentity {
    pub id: Option<String>,
}

// ---------------------------------------------------------------------------
// Synced policy config: `sync.toml` at the root of the sync-data store
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct SyncConfig {
    pub version: u32,
    pub jetbrains: JetbrainsConfig,
    pub plugins: PluginsConfig,
    pub xml: XmlConfig,
}

impl Default for SyncConfig {
    fn default() -> Self {
        Self {
            version: 1,
            jetbrains: JetbrainsConfig::default(),
            plugins: PluginsConfig::default(),
            xml: XmlConfig::default(),
        }
    }
}

impl SyncConfig {
    pub fn load(path: &std::path::Path) -> Result<Self> {
        read_toml(path)
    }

    pub fn save(&self, path: &std::path::Path) -> Result<()> {
        write_toml(path, self)
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct JetbrainsConfig {
    pub ides: Vec<String>,
    pub backups: bool,
    pub use_default_excludes: bool,
    pub explicit_include: Vec<String>,
    pub exclude: Vec<String>,
    /// `None` keeps the engine default of `["**", "*"]`.
    pub include: Option<Vec<String>>,
    pub vmoptions_names: BTreeMap<String, String>,
}

impl Default for JetbrainsConfig {
    fn default() -> Self {
        Self {
            ides: vec!["*20??.*".to_string()],
            backups: true,
            use_default_excludes: true,
            explicit_include: Vec::new(),
            exclude: Vec::new(),
            include: None,
            vmoptions_names: BTreeMap::new(),
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct PluginsConfig {
    pub enabled: bool,
    pub launchers: BTreeMap<String, String>,
    pub rule: Vec<PluginRule>,
    pub capability: Vec<PluginCapability>,
}

impl Default for PluginsConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            launchers: BTreeMap::new(),
            rule: Vec::new(),
            capability: Vec::new(),
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct PluginRule {
    pub id: String,
    #[serde(default = "wildcard")]
    pub ide: String,
    pub action: String,
}

/// What happened when a rule was written, so the caller can say so.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuleWrite {
    Added,
    /// The identical rule was already there, so the file was left alone.
    AlreadyPresent,
}

/// Appends a `[[plugins.rule]]` block to `sync.toml`.
///
/// Appends rather than re-serializing the whole config: `SyncConfig` would
/// round-trip every default into the file and drop the comments a person wrote
/// there. A new array-of-tables at the end is valid TOML whatever precedes it,
/// and last-match-wins means a later rule is also the one that takes effect.
pub fn append_plugin_rule(path: &std::path::Path, rule: &PluginRule) -> Result<RuleWrite> {
    let existing: SyncConfig = read_toml(path)?;
    if existing.plugins.rule.iter().any(|current| {
        current.id == rule.id && current.ide == rule.ide && current.action == rule.action
    }) {
        return Ok(RuleWrite::AlreadyPresent);
    }

    let mut contents = if path.exists() {
        std::fs::read_to_string(path)?
    } else {
        String::new()
    };
    if !contents.is_empty() && !contents.ends_with('\n') {
        contents.push('\n');
    }
    if !contents.is_empty() {
        contents.push('\n');
    }
    let _ = write!(
        contents,
        "[[plugins.rule]]\nid = \"{}\"\nide = \"{}\"\naction = \"{}\"\n",
        toml_escape(&rule.id),
        toml_escape(&rule.ide),
        toml_escape(&rule.action)
    );

    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, contents)?;
    Ok(RuleWrite::Added)
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct PluginCapability {
    #[serde(default = "wildcard")]
    pub ide: String,
    #[serde(default)]
    pub add: Vec<String>,
    #[serde(default)]
    pub remove: Vec<String>,
}

fn wildcard() -> String {
    "*".to_string()
}

/// Escapes the two characters that can end a TOML basic string early. Globs
/// bring `*`, `?` and brackets, none of which need escaping.
fn toml_escape(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct XmlConfig {
    pub use_defaults: bool,
    pub omit: Vec<XmlOmitRule>,
}

impl Default for XmlConfig {
    fn default() -> Self {
        Self {
            use_defaults: true,
            omit: Vec::new(),
        }
    }
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct XmlOmitRule {
    pub file: String,
    pub component: Option<String>,
    #[serde(default = "default_element")]
    pub element: String,
    pub option: Option<String>,
    pub attribute: Option<String>,
    #[serde(default)]
    pub equals: String,
}

fn default_element() -> String {
    "option".to_string()
}

// ---------------------------------------------------------------------------
// Per-machine override: `machines/<id>.toml` inside the sync-data store
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(default)]
pub struct MachineConfig {
    pub jetbrains: MachineJetbrainsConfig,
    pub xml: MachineXmlConfig,
}

impl MachineConfig {
    pub fn load(path: &std::path::Path) -> Result<Self> {
        read_toml(path)
    }
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(default)]
pub struct MachineJetbrainsConfig {
    pub exclude: Vec<String>,
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
#[serde(default)]
pub struct MachineXmlConfig {
    pub omit: Vec<XmlOmitRule>,
}

/// Sanitizes a raw machine identifier to `[A-Za-z0-9._-]`, matching the
/// filename-safety constraint on `machines/<id>.toml`.
pub fn sanitize_machine_id(raw: &str) -> String {
    let cleaned: String = raw
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-') {
                ch
            } else {
                '-'
            }
        })
        .collect();
    let trimmed = cleaned.trim_matches('-');
    if trimmed.is_empty() {
        "machine".to_string()
    } else {
        trimmed.to_string()
    }
}

pub fn machine_id(explicit: Option<&str>) -> String {
    let raw = explicit
        .map(str::to_string)
        .or_else(|| std::env::var("JBSYNC_MACHINE").ok())
        .or_else(|| hostname().map(|name| name.split('.').next().unwrap_or(&name).to_string()))
        .unwrap_or_else(|| "machine".to_string());
    sanitize_machine_id(&raw)
}

fn hostname() -> Option<String> {
    #[cfg(unix)]
    {
        std::process::Command::new("hostname")
            .output()
            .ok()
            .filter(|output| output.status.success())
            .and_then(|output| String::from_utf8(output.stdout).ok())
            .map(|value| value.trim().to_string())
    }
    #[cfg(not(unix))]
    {
        std::env::var("COMPUTERNAME").ok()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sanitizes_unsafe_characters() {
        assert_eq!(sanitize_machine_id("My Laptop!"), "My-Laptop");
        assert_eq!(sanitize_machine_id(""), "machine");
        assert_eq!(sanitize_machine_id("---"), "machine");
    }

    #[test]
    fn default_sync_config_matches_engine_defaults() {
        let config = SyncConfig::default();
        assert_eq!(config.jetbrains.ides, vec!["*20??.*"]);
        assert!(config.jetbrains.backups);
        assert!(config.jetbrains.use_default_excludes);
        assert!(config.plugins.enabled);
    }

    #[test]
    fn appending_a_rule_keeps_the_comments_around_it() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("sync.toml");
        std::fs::write(&path, "# hand written\n[jetbrains]\nbackups = false\n").unwrap();

        let rule = PluginRule {
            id: "com.falsepattern.zigbrains".to_string(),
            ide: "CLion*".to_string(),
            action: "only".to_string(),
        };
        assert_eq!(append_plugin_rule(&path, &rule).unwrap(), RuleWrite::Added);

        let text = std::fs::read_to_string(&path).unwrap();
        assert!(text.contains("# hand written"), "{text}");
        let loaded = SyncConfig::load(&path).unwrap();
        assert!(!loaded.jetbrains.backups, "existing settings must survive");
        assert_eq!(loaded.plugins.rule.len(), 1);
        assert_eq!(loaded.plugins.rule[0].action, "only");
        assert_eq!(loaded.plugins.rule[0].ide, "CLion*");
    }

    #[test]
    fn appending_the_same_rule_twice_changes_nothing() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("sync.toml");
        let rule = PluginRule {
            id: "com.example.tool".to_string(),
            ide: "*".to_string(),
            action: "deny".to_string(),
        };
        append_plugin_rule(&path, &rule).unwrap();
        let once = std::fs::read_to_string(&path).unwrap();
        assert_eq!(
            append_plugin_rule(&path, &rule).unwrap(),
            RuleWrite::AlreadyPresent
        );
        assert_eq!(std::fs::read_to_string(&path).unwrap(), once);
    }

    #[test]
    fn a_rule_written_into_a_missing_file_still_parses() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("nested").join("sync.toml");
        let rule = PluginRule {
            id: "com.example.tool".to_string(),
            ide: "RustRover*".to_string(),
            action: "only".to_string(),
        };
        append_plugin_rule(&path, &rule).unwrap();
        let loaded = SyncConfig::load(&path).unwrap();
        assert_eq!(loaded.plugins.rule.len(), 1);
        assert_eq!(loaded.plugins.rule[0].id, "com.example.tool");
    }

    #[test]
    fn round_trips_through_toml() {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("sync.toml");
        let mut config = SyncConfig::default();
        config.jetbrains.exclude.push("options/foo.xml".to_string());
        config.save(&path).unwrap();
        let loaded = SyncConfig::load(&path).unwrap();
        assert_eq!(loaded.jetbrains.exclude, vec!["options/foo.xml"]);
    }
}

