    #[test]
    fn the_manifest_is_pooled_across_ides() {
        let directory = tempfile::tempdir().unwrap();
        let with_tree = directory.path().join("IntelliJIdea2026.2");
        let without_tree = directory.path().join("WebStorm2026.2");
        std::fs::create_dir_all(with_tree.join("settingsSync/options")).unwrap();
        std::fs::create_dir_all(without_tree.join("options")).unwrap();
        std::fs::write(
            with_tree.join("settingsSync/options/laf.xml"),
            "<application />",
        )
        .unwrap();

        let first = ide_at(&with_tree, "IntelliJIdea", "idea.vmoptions");
        let second = ide_at(&without_tree, "WebStorm", "webstorm.vmoptions");
        let manifest = learned_manifest(&[&first, &second], &[]);
        assert!(manifest.contains(&"options/laf.xml".to_string()));
        assert_eq!(
            observed_manifest(&[&first, &second]),
            vec!["options/laf.xml".to_string()],
            "only what an IDE proved is published back to the store"
        );

        // The IDE with no tree of its own still gets the pooled allowlist, and
        // nothing outside it — `other.xml` is not roamed by JetBrains.
        std::fs::write(without_tree.join("options/laf.xml"), "<application />").unwrap();
        std::fs::write(without_tree.join("options/other.xml"), "<application />").unwrap();
        let found = discover(&second, &SyncConfig::default(), &manifest).unwrap();
        assert!(found.contains_key("options/laf.xml"));
        assert!(!found.contains_key("options/other.xml"));
    }

    #[test]
    fn without_any_learned_tree_the_builtin_list_applies() {
        let directory = tempfile::tempdir().unwrap();
        let ide = ide_at(directory.path(), "WebStorm", "webstorm.vmoptions");
        let manifest = learned_manifest(&[&ide], &[]);
        assert!(manifest.contains(&"options/editor.xml".to_string()));
        assert!(
            !manifest.iter().any(|entry| entry == "options/other.xml"),
            "per-machine UI state must never be in the fallback list"
        );
    }

    /// The point of remembering: a machine with no `settingsSync` tree of its
    /// own still syncs what another machine proved roams.
    #[test]
    fn a_remembered_entry_widens_the_manifest() {
        let directory = tempfile::tempdir().unwrap();
        let ide = ide_at(directory.path(), "WebStorm", "webstorm.vmoptions");
        let remembered = vec!["options/unusual.xml".to_string()];
        let manifest = learned_manifest(&[&ide], &remembered);
        assert!(manifest.contains(&"options/unusual.xml".to_string()));
        // Remembering must not narrow the floor the built-in list provides.
        assert!(manifest.contains(&"options/editor.xml".to_string()));
        assert!(
            observed_manifest(&[&ide]).is_empty(),
            "this machine observed nothing, so it publishes nothing"
        );
    }

    #[test]
    fn settings_sync_tombstones_are_not_adopted() {
        let directory = tempfile::tempdir().unwrap();
        let root = directory.path();
        std::fs::create_dir_all(root.join("settingsSync/options")).unwrap();
        std::fs::write(root.join("settingsSync/options/terminal.xml"), "DELETED").unwrap();
        std::fs::write(root.join("settingsSync/options/laf.xml"), "<application />").unwrap();

        let ide = ide_at(root, "IntelliJIdea", "idea.vmoptions");
        let manifest = settings_sync_manifest(&ide);
        assert!(manifest.contains(&"options/laf.xml".to_string()));
        assert!(!manifest.contains(&"options/terminal.xml".to_string()));
    }
}
//! Keeping only settings the user actually chose.
//!
//! The IntelliJ platform already does most of this work: when a component's
//! state equals the state produced by its default constructor, nothing is
//! written to XML at all. So a live `options/*.xml` is close to a diff against
//! defaults before `jbsync` touches it.
//!
//! What remains is residue of three kinds, and each gets a declarative rule
//! rather than bespoke code:
//!
//!   * components that serialize a whole map, including untouched entries
//!     (tutorial progress, inlay-hint tables);
//!   * values the IDE set for itself rather than for the user (registry keys
//!     carrying `source="SYSTEM"` or `"MANAGER"`, one-shot migration flags);
//!   * components that persist only a schema version and no settings;
//!   * dialog state the platform files alongside real settings, which is what
//!     `project.default.xml` needs before it can be shared at all.
//!
//! Rules are data, so covering a newly noisy component is a table entry here
//! or an `[[xml.omit]]` block in `sync.toml` — never a new code path.

use crate::{
    config::XmlOmitRule, settings::defaults::ProductDefaults, xml::dom::Element, xml::project,
};

/// Attributes that describe the file format rather than a user's choice. A
/// component carrying only these, with no children, holds no settings.
const BOOKKEEPING_ATTRIBUTES: [&str; 2] = ["name", "version"];

struct Builtin {
    file: &'static str,
    component: Option<&'static str>,
    element: &'static str,
    attribute: &'static str,
    equals: &'static str,
    reason: &'static str,
}

/// Values written by the IDE for its own purposes. Registry keys record where
/// they came from; anything not attributable to the user is not a setting we
/// want to carry between machines.
const BUILTINS: &[Builtin] = &[
    Builtin {
        file: "options/ide.general.xml",
        component: Some("Registry"),
        element: "entry",
        attribute: "source",
        equals: "SYSTEM",
        reason: "registry key set by the IDE, not the user",
    },
    Builtin {
        file: "options/ide.general.xml",
        component: Some("Registry"),
        element: "entry",
        attribute: "source",
        equals: "MANAGER",
        reason: "registry key managed centrally, not by the user",
    },
    Builtin {
        file: "options/ide-features-trainer.xml",
        component: Some("LessonStateBase"),
        element: "entry",
        attribute: "value",
        equals: "NOT_PASSED",
        reason: "tutorial never started",
    },
    Builtin {
        file: "options/*.xml",
        component: None,
        element: "option",
        attribute: "name",
        equals: "MIGRATE_OLD_SETTINGS",
        reason: "one-shot settings migration flag",
    },
    Builtin {
        file: "options/other.xml",
        component: Some("LangManager"),
        element: "entry",
        attribute: "key",
        equals: "JAVA",
        reason: "per-installation language state",
    },
];

/// Content that is machine-local rather than merely not-a-choice, which is why
/// these run whatever `xml.use_defaults` says.
///
/// Turning that setting off widens what counts as a user choice — it keeps
/// registry keys and tutorial progress. That is not a reason to start
/// publishing another machine's window positions, and `project.default.xml` is
/// only in the manifest at all because these rules can take this content out of
/// it. Gating them on the same flag would mean a single unrelated preference
/// silently turned the exception into a leak.
///
/// `project.default.xml` is the template every new project starts from, so most
/// of it is a genuine choice — but the platform stores dialog state in the same
/// file. These four are the ones that appear there, identical across IntelliJ
/// IDEA, PyCharm, CLion, RustRover and WebStorm. Each is dropped as a whole
/// component: none of them has a leaf worth keeping, and matching the component
/// is what makes the rule survive JetBrains adding another field to it.
const ALWAYS: &[Builtin] = &[
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "WindowStateProjectService",
        reason: "dialog geometry, in this machine's screen coordinates",
    },
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "masterDetails",
        reason: "splitter positions in the settings dialog",
    },
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "ProjectInspectionProfilesVisibleTreeState",
        reason: "which inspection tree nodes were left expanded",
    },
    // One `#text` leaf holding a whole JSON document. Everything here —
    // pruning, merging, reporting, conflict resolution — addresses XML leaves,
    // so nothing inside that blob can be reached without a second
    // implementation of all four. That is the same objection that keeps
    // `llm.*.xml` out of the manifest.
    //
    // This one is not free, and the cost is worth naming: the blob mixes real
    // choices (`rearrange.code.on.save`, the third checkbox in Actions on Save,
    // whose two siblings *are* synced above) with pure dialog state
    // (`settings.editor.selected.configurable`, which changes every time you
    // open a different settings page) and with keys that hold absolute paths on
    // machines where the package was not auto-detected. Filtering by key would
    // still leave one unmergeable leaf, and would have to choose between
    // leaking those paths and silently dropping keys JetBrains adds later.
    // Sharing settings this file *can* represent beats sharing none of it; if
    // per-key handling is ever worth building, it belongs in its own change.
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "PropertiesComponent",
        reason: "opaque JSON blob of UI state and machine-local paths",
    },
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Removal {
    /// Human-readable address, as shown in reports.
    pub path: String,
    pub reason: String,
}

#[derive(Debug, Clone, Default)]
pub struct PruneOutcome {
    pub removed: Vec<Removal>,
    /// True when nothing worth storing survived, so the file itself can be
    /// dropped from the store.
    pub is_empty: bool,
}

fn file_matches(pattern: &str, relative: &str) -> bool {
    globset::Glob::new(pattern).is_ok_and(|glob| glob.compile_matcher().is_match(relative))
}

/// True when `element` is one the rule targets, given the component it sits in.
fn rule_matches(
    element: &Element,
    component: Option<&str>,
    rule_component: Option<&str>,
    rule_element: &str,
    attribute: Option<&str>,
    option: Option<&str>,
    equals: &str,
) -> bool {
    if element.name != rule_element {
        return false;
    }
    if let Some(wanted) = rule_component
        && component != Some(wanted)
    {
        return false;
    }
    if let Some(name) = option {
        return element.attributes.get("name").map(String::as_str) == Some(name);
    }
    let Some(attribute) = attribute else {
        return false;
    };
    element.attributes.get(attribute).map(String::as_str) == Some(equals)
}

/// Removes non-setting content from `root`, reporting what went and why.
/// `defaults`, when present, are the values this product shipped with, captured
/// from an install nobody had opened yet. A setting still holding its default is
/// not a choice, so it is removed here — before the bottom-up cleanup, so the
/// component it lived in disappears too rather than lingering as an empty shell.
pub fn prune_document(
    relative: &str,
    root: &mut Element,
    rules: &[XmlOmitRule],
    use_builtins: bool,
    defaults: Option<&ProductDefaults>,
) -> PruneOutcome {
    let mut removed = Vec::new();

    // The machine-local rules are not optional; the rest answer "is this a user
    // choice", which is the question `use_builtins` is about.
    let gated = if use_builtins { BUILTINS } else { &[] };
    for rule in ALWAYS
        .iter()
        .chain(gated)
        .filter(|rule| file_matches(rule.file, relative))
    {
        apply(
            root,
            None,
            "",
            rule.component,
            rule.element,
            Some(rule.attribute),
            None,
            rule.equals,
            rule.reason,
            &mut removed,
        );
    }
    for rule in rules
        .iter()
        .filter(|rule| file_matches(&rule.file, relative))
    {
        let reason = format!("excluded by {}", rule.file);
        apply(
            root,
            None,
            "",
            rule.component.as_deref(),
            &rule.element,
            rule.attribute.as_deref(),
            rule.option.as_deref(),
            &rule.equals,
            &reason,
            &mut removed,
        );
    }

    if let Some(defaults) = defaults {
        let untouched: Vec<String> = project::project(root)
            .into_iter()
            .filter(|(address, value)| defaults.value(relative, address) == Some(value.as_str()))
            .map(|(address, _)| address)
            .collect();
        for address in untouched {
            project::remove_leaf(root, &address);
            removed.push(Removal {
                path: project::sugar(&address),
                reason: "unchanged from this product's default".to_string(),
            });
        }
    }

    // Bottom-up: a component only looks settingless once the wrappers its
    // removed entries lived in have themselves gone, and a wrapper only looks
    // empty once the settingless components inside it have gone. Doing both in
    // one upward pass settles that mutual dependency at every depth.
    clear_out(root, &mut removed);

    PruneOutcome {
        is_empty: root.children.is_empty() && root.attributes.is_empty(),
        removed,
    }
}

#[allow(clippy::too_many_arguments)]
fn apply(
    element: &mut Element,
    component: Option<&str>,
    path: &str,
    rule_component: Option<&str>,
    rule_element: &str,
    attribute: Option<&str>,
    option: Option<&str>,
    equals: &str,
    reason: &str,
    removed: &mut Vec<Removal>,
) {
    // A `<component name=...>` establishes the scope rules are written against.
    let scope = if element.name == "component" {
        element.attributes.get("name").map(String::as_str)
    } else {
        component
    };

    element.children.retain(|child| {
        let matched = rule_matches(
            child,
            scope,
            rule_component,
            rule_element,
            attribute,
            option,
            equals,
        );
        if matched {
            removed.push(Removal {
                path: describe(path, child),
                reason: reason.to_string(),
            });
        }
        !matched
    });

    let scope = scope.map(str::to_string);
    for child in &mut element.children {
        let child_path = describe(path, child);
        apply(
            child,
            scope.as_deref(),
            &child_path,
            rule_component,
            rule_element,
            attribute,
            option,
            equals,
            reason,
            removed,
        );
    }
}

/// A readable address for an element, used only in reports.
fn describe(parent_path: &str, element: &Element) -> String {
    let own = element
        .key_attribute()
        .map_or_else(|| element.name.clone(), |(_, value)| value.to_string());
    if parent_path.is_empty() {
        own
    } else {
        format!("{parent_path}/{own}")
    }
}

/// Removes everything left holding nothing: containers a rule emptied, and
/// components that persist a schema version but no settings.
///
/// Children are cleared before their parent is judged, so one pass is enough
/// however deep the nesting goes. Depth matters for `project.default.xml`,
/// where a component sits inside `<defaultProject>` inside another component:
/// emptying the innermost one has to retire both the wrapper around it and the
/// `ProjectManager` shell around that, or the file never reduces to "no
/// opinion" and every machine keeps publishing an empty skeleton.
fn clear_out(element: &mut Element, removed: &mut Vec<Removal>) {
    for child in &mut element.children {
        clear_out(child, removed);
    }
    element.children.retain(|child| {
        if child.is_valueless() {
            return false;
        }
        let settingless = child.name == "component"
            && child.children.is_empty()
            && child.text.is_none()
            && child
                .attributes
                .keys()
                .all(|key| BOOKKEEPING_ATTRIBUTES.contains(&key.as_str()));
        if settingless {
            removed.push(Removal {
                path: describe("", child),
                reason: "component stores no settings".to_string(),
            });
        }
        !settingless
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::xml::dom::parse;

    fn prune(relative: &str, source: &str) -> (Element, PruneOutcome) {
        let mut root = parse(source).unwrap();
        let outcome = prune_document(relative, &mut root, &[], true, None);
        (root, outcome)
    }

    #[test]
    fn keeps_user_registry_keys_and_drops_ide_owned_ones() {
        let (root, outcome) = prune(
            "options/ide.general.xml",
            r#"<application>
                 <component name="Registry">
                   <entry key="ide.experimental.ui" value="true" source="SYSTEM" />
                   <entry key="trace.url" value="https://x" source="MANAGER" />
                   <entry key="my.tweak" value="true" source="USER" />
                   <entry key="older.style" value="true" />
                 </component>
               </application>"#,
        );
        let kept: Vec<&str> = root.children[0]
            .children
            .iter()
            .filter_map(|entry| entry.attributes.get("key").map(String::as_str))
            .collect();
        assert_eq!(kept, vec!["my.tweak", "older.style"]);
        assert_eq!(outcome.removed.len(), 2);
    }

    /// A setting still holding the value its product shipped with is not a
    /// choice, and the component it lived in should go with it.
    #[test]
    fn a_value_matching_the_products_default_is_not_a_choice() {
        let mut root = crate::xml::dom::parse(
            "<application>\n  <component name=\"Editor\">\n    <option name=\"tabs\" value=\"4\" />\n    <option name=\"wrap\" value=\"true\" />\n  </component>\n</application>",
        )
        .unwrap();
        let mut defaults = ProductDefaults::new("WebStorm", "262.1");
        defaults.record(
            "options/editor.xml",
            crate::xml::project::project(&root).into_iter().collect(),
        );

        // Everything matches the default, so nothing is worth sharing.
        let mut untouched = root.clone();
        let outcome = prune_document(
            "options/editor.xml",
            &mut untouched,
            &[],
            true,
            Some(&defaults),
        );
        assert!(
            outcome.is_empty,
            "an untouched file has no opinion, and leaves no empty shells"
        );

        // Change one of the two; only that one survives.
        let donor = root.clone();
        crate::xml::project::set_leaf(
            &mut root,
            &donor,
            "component[name=Editor]/option[name=tabs]/@value",
            "8",
        );
        let outcome = prune_document("options/editor.xml", &mut root, &[], true, Some(&defaults));
        assert!(!outcome.is_empty);
        let kept: Vec<String> = crate::xml::project::project(&root)
            .into_keys()
            .map(|address| crate::xml::project::sugar(&address))
            .collect();
        assert_eq!(kept, vec!["Editor/tabs".to_string()]);
    }

    #[test]
    fn drops_untouched_tutorial_progress_entirely() {
        let (_, outcome) = prune(
            "options/ide-features-trainer.xml",
            r#"<application>
                 <component name="LessonStateBase">
                   <option name="map">
                     <map>
                       <entry key="actions" value="NOT_PASSED" />
                       <entry key="collapse" value="NOT_PASSED" />
                     </map>
                   </option>
                 </component>
               </application>"#,
        );
        assert!(
            outcome.is_empty,
            "a file of untouched defaults should not reach the store"
        );
    }

    #[test]
    fn keeps_tutorials_the_user_completed() {
        let (root, _) = prune(
            "options/ide-features-trainer.xml",
            r#"<application>
                 <component name="LessonStateBase">
                   <option name="map">
                     <map>
                       <entry key="actions" value="NOT_PASSED" />
                       <entry key="collapse" value="PASSED" />
                     </map>
                   </option>
                 </component>
               </application>"#,
        );
        let flattened = crate::xml::project::project(&root);
        assert_eq!(flattened.len(), 1);
        assert!(flattened.keys().next().unwrap().contains("collapse"));
    }

    #[test]
    fn drops_version_only_components_but_keeps_real_settings() {
        let (root, _) = prune(
            "options/databaseDrivers.xml",
            r#"<application>
                 <component name="LocalDatabaseDriverManager" version="201" />
                 <component name="LafManager" autodetect="true" />
               </application>"#,
        );
        assert_eq!(root.children.len(), 1);
        assert_eq!(
            root.children[0].attributes.get("name").map(String::as_str),
            Some("LafManager")
        );
    }

    #[test]
    fn drops_one_shot_migration_flags() {
        let (_, outcome) = prune(
            "options/diff.xml",
            r#"<application>
                 <component name="ExternalDiffSettings">
                   <option name="MIGRATE_OLD_SETTINGS" value="true" />
                 </component>
               </application>"#,
        );
        assert!(outcome.is_empty);
    }

    /// Shaped like the real file: `<defaultProject>` holds a component per
    /// project setting, mixed in with the dialog state the platform keeps
    /// beside them.
    fn default_project(body: &str) -> String {
        format!(
            r#"<application>
                 <component name="ProjectManager">
                   <defaultProject>{body}</defaultProject>
                 </component>
               </application>"#
        )
    }

    #[test]
    fn settings_for_new_projects_are_kept_and_dialog_state_is_not() {
        let (root, outcome) = prune(
            "options/project.default.xml",
            &default_project(
                r##"<component name="TypeScriptCompiler">
                     <option name="memoryAutoIncrease" value="true" />
                   </component>
                   <component name="FormatOnSaveOptions">
                     <option name="myRunOnSave" value="true" />
                   </component>
                   <component name="WindowStateProjectService">
                     <state x="356" y="76" key="#Plugins" timestamp="1785330308665">
                       <screen x="0" y="33" width="1512" height="876" />
                     </state>
                   </component>
                   <component name="masterDetails">
                     <states><state key="Copyright.UI" /></states>
                   </component>
                   <component name="ProjectInspectionProfilesVisibleTreeState">
                     <entry key="Project Default" />
                   </component>
                   <component name="PropertiesComponent">{"keyToString": {"a": "b"}}</component>"##,
            ),
        );

        let kept: Vec<String> = project::project(&root)
            .into_keys()
            .map(|address| project::sugar(&address))
            .collect();
        assert_eq!(
            kept,
            vec![
                "New Projects/FormatOnSaveOptions/myRunOnSave".to_string(),
                "New Projects/TypeScriptCompiler/memoryAutoIncrease".to_string(),
            ],
            "only the settings survive, and they read like the settings UI"
        );
        assert!(!outcome.is_empty);
        // Every removal names the component it took out, so `status --verbose`
        // can explain the file rather than just shrinking it.
        let removed: Vec<&str> = outcome
            .removed
            .iter()
            .map(|removal| removal.path.as_str())
            .collect();
        assert!(
            removed.contains(&"ProjectManager/defaultProject/WindowStateProjectService"),
            "{removed:?}"
        );
        assert!(
            removed.contains(&"ProjectManager/defaultProject/PropertiesComponent"),
            "{removed:?}"
        );
    }

    /// The wrappers are three deep, so emptying the innermost component has to
    /// retire `<defaultProject>` and the `ProjectManager` shell as well.
    /// Otherwise the file never reduces to "no opinion" and every machine keeps
    /// republishing an empty skeleton.
    #[test]
    fn a_default_project_holding_only_dialog_state_has_no_opinion() {
        let (root, outcome) = prune(
            "options/project.default.xml",
            &default_project(
                r##"<component name="WindowStateProjectService">
                     <state x="356" y="76" key="#Plugins" />
                   </component>
                   <component name="masterDetails">
                     <states><state key="Copyright.UI" /></states>
                   </component>"##,
            ),
        );
        assert!(
            outcome.is_empty,
            "left {:?}",
            crate::xml::dom::serialize(&root)
        );
    }

    /// The rules are written against the component, not against the fields
    /// inside it, so a component the platform grows a new field for still goes
    /// wholesale rather than leaking the addition.
    #[test]
    fn dialog_state_goes_wholesale_even_with_unfamiliar_fields() {
        let (root, _) = prune(
            "options/project.default.xml",
            &default_project(
                r##"<component name="WindowStateProjectService">
                     <state key="#Plugins" somethingNew="17" />
                     <freshElement value="7" />
                   </component>
                   <component name="AutoImportSettings">
                     <option name="autoReloadType" value="SELECTIVE" />
                   </component>"##,
            ),
        );
        let kept = project::project(&root);
        assert_eq!(kept.len(), 1);
        assert!(
            !kept.keys().any(|address| address.contains("WindowState")),
            "{kept:?}"
        );
    }

    /// Same component name, different file: `PropertiesComponent` in
    /// `other.xml` is application state jbsync has never claimed to prune, and
    /// the new rules must not start reaching into it.
    #[test]
    fn the_default_project_rules_are_scoped_to_that_file() {
        let (root, _) = prune(
            "options/other.xml",
            r#"<application>
                 <component name="PropertiesComponent">{"keyToString": {"a": "b"}}</component>
               </application>"#,
        );
        assert_eq!(root.children.len(), 1);
    }

    /// `xml.use_defaults = false` widens what counts as a user choice. It must
    /// not also start publishing machine-local content: this file is only in
    /// the manifest because these four rules can take that content out of it,
    /// so one unrelated preference would otherwise turn the exception into a
    /// leak on upgrade.
    #[test]
    fn dialog_state_goes_even_with_the_builtin_rules_turned_off() {
        let mut root = parse(&default_project(
            r##"<component name="AutoImportSettings">
                   <option name="autoReloadType" value="SELECTIVE" />
                 </component>
                 <component name="WindowStateProjectService">
                   <state x="356" y="76" key="#Plugins" />
                 </component>
                 <component name="PropertiesComponent">{"keyToString": {"a": "/Users/someone/x"}}</component>"##,
        ))
        .unwrap();
        let outcome = prune_document("options/project.default.xml", &mut root, &[], false, None);

        let serialized = crate::xml::dom::serialize(&root);
        assert!(
            !serialized.contains("WindowStateProjectService"),
            "{serialized}"
        );
        assert!(!serialized.contains("/Users/someone"), "{serialized}");
        assert!(serialized.contains("autoReloadType"), "{serialized}");
        assert!(!outcome.is_empty);

        // The rules that answer "is this a user choice" really are off, so the
        // two categories have not merely been merged.
        let mut registry = parse(
            r#"<application><component name="Registry">
                 <entry key="a" value="1" source="SYSTEM" />
               </component></application>"#,
        )
        .unwrap();
        prune_document("options/ide.general.xml", &mut registry, &[], false, None);
        assert!(crate::xml::dom::serialize(&registry).contains("SYSTEM"));
    }

    #[test]
    fn user_rules_apply_on_top_of_builtins() {
        let mut root = parse(
            r#"<application>
                 <component name="EditorSettings">
                   <option name="SHOW_INTENTION_BULB" value="false" />
                   <option name="IS_CARET_BLINKING" value="true" />
                 </component>
               </application>"#,
        )
        .unwrap();
        let rules = vec![XmlOmitRule {
            file: "options/editor.xml".to_string(),
            component: Some("EditorSettings".to_string()),
            element: "option".to_string(),
            option: Some("SHOW_INTENTION_BULB".to_string()),
            attribute: None,
            equals: String::new(),
        }];
        let outcome = prune_document("options/editor.xml", &mut root, &rules, true, None);
        assert_eq!(outcome.removed.len(), 1);
        assert_eq!(root.children[0].children.len(), 1);
    }

    #[test]
    fn rules_scoped_to_other_files_do_not_fire() {
        let mut root = parse(
            r#"<application><component name="Registry">
                 <entry key="a" value="1" source="SYSTEM" />
               </component></application>"#,
        )
        .unwrap();
        let outcome = prune_document("options/editor.xml", &mut root, &[], true, None);
        assert!(outcome.removed.is_empty());
    }
}

