                        &action.plugin,
                        &self.sync_config.plugins,
                    )?;
                }
            } else {
                lines.push(format!(
                    "{}: skip {} ({})",
                    action.ide, action.plugin, action.reason
                ));
            }
        }
        Ok(PluginOutcome {
            lines,
            manifest_changed,
        })
    }

    /// Turns off JetBrains' bundled Backup and Sync.
