        self.backend.workdir()
    }

    fn shared_path(&self, relative: &str) -> PathBuf {
        self.store_root().join(SHARED).join(relative)
    }

    fn base_path(&self, ide: &Ide, relative: &str) -> PathBuf {
        self.paths
            .base_dir()
            .join(directory_name(ide))
            .join(relative)
