                let mut donor = dom::Element::new("application");
                let mut component = dom::Element::new("component");
                component
                    .attributes
                    .insert("name".to_string(), component_name.to_string());
                let mut option = dom::Element::new("option");
                option

item.stdout:
                option
                    .attributes
