                                    project::set_leaf(&mut target, &donor, &change.path, value);
                                }
                                None => project::remove_leaf(&mut target, &change.path),
                            }
                        }
                        dom::serialize(&target).into_bytes()
                    }
                    _ => content.clone(),
                }
            }
