            return Ok(());
        }
        if self.sync_config.jetbrains.backups && raw.is_some() {
            let backup = self
                .paths
                .backups_dir()
                .join(stamp)
                .join(directory_name(ide))
                .join(relative);
            staging.write(&backup, raw)?;
        }
        staging.write(ide_file, Some(&updated))
    }
}

