}

/// Escapes the two characters that can end a TOML basic string early. Globs
/// bring `*`, `?` and brackets, none of which need escaping.
fn toml_escape(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

