//! learned once, by any machine, forever.

use std::collections::BTreeSet;

use serde::{Deserialize, Serialize};

use crate::error::{JbsyncError, Result};

/// Filename at the root of the store.
pub const FILE_NAME: &str = "manifest.toml";

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct StoredManifest {
    pub version: u32,
    /// Store-relative glob patterns, sorted. Union of every `settingsSync`
    /// tree any machine has ever observed.
    pub roamable: Vec<String>,
}

impl Default for StoredManifest {
    fn default() -> Self {
        Self {
            version: 1,
            roamable: Vec::new(),
        }
    }
}

impl StoredManifest {
    pub fn load(path: &std::path::Path) -> Result<Self> {
        if !path.exists() {
            return Ok(Self::default());
        }
        let contents = std::fs::read_to_string(path)?;
        toml::from_str(&contents)
            .map_err(|error| JbsyncError::configuration(format!("{}: {error}", path.display())))
    }

    pub fn encode(&self) -> Result<String> {
        toml::to_string_pretty(self).map_err(|error| JbsyncError::configuration(error.to_string()))
    }

    /// Folds newly observed entries in, returning `true` when that added
    /// something. Entries are never removed: an IDE being uninstalled, or
    /// Backup and Sync being switched off, is not evidence that a file stopped
    /// being roamable.
    pub fn absorb(&mut self, observed: &[String]) -> bool {
        let before = self.roamable.len();
        let mut merged: BTreeSet<String> = self.roamable.drain(..).collect();
        merged.extend(observed.iter().cloned());
        self.roamable = merged.into_iter().collect();
        self.roamable.len() != before
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn absorbing_is_a_growing_union() {
        let mut manifest = StoredManifest::default();
        assert!(manifest.absorb(&["options/editor.xml".to_string()]));
        assert!(manifest.absorb(&["options/laf.xml".to_string()]));
        // Already known, so nothing changes and no commit is provoked.
        assert!(!manifest.absorb(&["options/editor.xml".to_string()]));
        assert_eq!(manifest.roamable, ["options/editor.xml", "options/laf.xml"]);
    }

    #[test]
    fn an_ide_disappearing_does_not_shrink_the_record() {
        let mut manifest = StoredManifest::default();
        manifest.absorb(&["options/editor.xml".to_string()]);
        // A machine with no settingsSync tree at all observes nothing.
        assert!(!manifest.absorb(&[]));
        assert_eq!(manifest.roamable, ["options/editor.xml"]);
    }

    #[test]
    fn round_trips_through_toml() {
        let mut manifest = StoredManifest::default();
        manifest.absorb(&["options/editor.xml".to_string()]);
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join(FILE_NAME);
        std::fs::write(&path, manifest.encode().unwrap()).unwrap();
        let loaded = StoredManifest::load(&path).unwrap();
        assert_eq!(loaded.roamable, manifest.roamable);
        assert_eq!(loaded.version, 1);
    }
}
//! Where jbsync keeps its own local state, as distinct from the sync-data
//! store the backend replicates. Mirrors XFER's `~/.xfer`-style layout via
//! `rust_cli_toolkit::SecureDir`.

use std::path::{Path, PathBuf};

use rust_cli_toolkit::{LockGuard, SecureDir};

use crate::{config::RepoConfig, error::Result};

pub struct Paths {
    app_dir: SecureDir,
}

impl Paths {
    pub fn discover(override_root: Option<PathBuf>) -> Result<Self> {
        Ok(Self {
            app_dir: SecureDir::discover("jbsync", override_root)?,
        })
    }

    pub fn app_root(&self) -> &Path {
        self.app_dir.root()
    }

    pub fn local_config_path(&self) -> PathBuf {
        self.app_dir.path("config.toml")
    }

    /// The local working copy of the sync-data store (`shared/`, `machines/`,
    /// `sync.toml`, `plugins.json`), defaulting under the app directory unless
    /// `repo.path` overrides it.
    pub fn data_dir(&self, repo: &RepoConfig) -> PathBuf {
        repo.path
            .clone()
            .unwrap_or_else(|| self.app_dir.root().join("data"))
    }

    /// Per-IDE snapshots of the last state that IDE and the store agreed on.
    /// This is the `base` of every three-way merge, so it has to hold real
    /// content rather than a digest.
    pub fn base_dir(&self) -> PathBuf {
        self.app_dir.root().join("base")
    }

    /// Timestamped copies of IDE files, taken before they are overwritten.
    pub fn backups_dir(&self) -> PathBuf {
        self.app_dir.root().join("backups")
    }

    /// Takes the lock that serializes whole syncs.
    ///
    /// A sync reads the IDEs, rewrites the store, and writes back — two runs
    /// overlapping (a shell and an editor hook, say) could interleave those
    /// steps and publish a half-merged result. Reports `None` rather than
    /// waiting, so the caller can say a run is already in progress.
    pub fn try_lock(&self) -> Result<Option<LockGuard>> {
        Ok(self.app_dir.try_lock_exclusive("sync.lock")?)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_dir_defaults_under_app_root() {
        let directory = tempfile::tempdir().unwrap();
        let paths = Paths::discover(Some(directory.path().to_path_buf())).unwrap();
        let repo = RepoConfig::default();
        assert_eq!(paths.data_dir(&repo), directory.path().join("data"));
    }

    #[test]
    fn data_dir_honors_explicit_override() {
        let directory = tempfile::tempdir().unwrap();
        let paths = Paths::discover(Some(directory.path().to_path_buf())).unwrap();
        let repo = RepoConfig {
            path: Some(PathBuf::from("/custom/data")),
            ..RepoConfig::default()
        };
        assert_eq!(paths.data_dir(&repo), PathBuf::from("/custom/data"));
    }
}
//! OS-specific discovery of the `JetBrains` config root and installation search roots.

use std::path::PathBuf;

pub fn default_jetbrains_root() -> PathBuf {
    let home = dirs_home();
    if cfg!(target_os = "macos") {
        return home.join("Library/Application Support/JetBrains");
    }
    if cfg!(target_os = "windows") {
        let appdata = std::env::var_os("APPDATA").map_or_else(|| home.clone(), PathBuf::from);
        return appdata.join("JetBrains");
    }
    let config_home =
        std::env::var_os("XDG_CONFIG_HOME").map_or_else(|| home.join(".config"), PathBuf::from);
    config_home.join("JetBrains")
}

pub fn default_install_roots() -> Vec<PathBuf> {
    let home = dirs_home();
    if cfg!(target_os = "macos") {
        return vec![
            PathBuf::from("/Applications"),
            home.join("Applications"),
            home.join("Library/Application Support/JetBrains/Toolbox/apps"),
        ];
    }
    if cfg!(target_os = "windows") {
        let mut roots = vec![
            std::env::var_os("PROGRAMFILES")
                .map_or_else(|| PathBuf::from("C:/Program Files"), PathBuf::from)
                .join("JetBrains"),
            std::env::var_os("LOCALAPPDATA")
                .map_or_else(|| home.join("AppData/Local"), PathBuf::from)
                .join("JetBrains/Toolbox/apps"),
        ];
        if let Some(program_files_x86) = std::env::var_os("PROGRAMFILES(X86)") {
            roots.push(PathBuf::from(program_files_x86).join("JetBrains"));
        }
        return roots;
    }
    vec![
        PathBuf::from("/opt"),
        home.join(".local/share/JetBrains/Toolbox/apps"),
        home.join(".local/share/JetBrains"),
    ]
}

fn dirs_home() -> PathBuf {
    dirs::home_dir().unwrap_or_else(|| PathBuf::from("."))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn jetbrains_root_is_non_empty() {
        assert!(default_jetbrains_root().components().count() > 0);
    }

    #[test]
    fn install_roots_are_non_empty() {
        assert!(!default_install_roots().is_empty());
    }
}

