        "IntelliJIdea2026.2",
        "editor.xml",
        "Editor",
        &[("tabs", "2"), ("fontSize", "15")],
    );
    first.sync();

    // A brand new machine, with the IDE present but no settings of its own.
    let second = Machine::new(remote.path(), &["IntelliJIdea2026.2"]);
