//! Keeping only settings the user actually chose.
//!
//! The IntelliJ platform already does most of this work: when a component's
//! state equals the state produced by its default constructor, nothing is
//! written to XML at all. So a live `options/*.xml` is close to a diff against
//! defaults before `jbsync` touches it.
//!
//! What remains is residue of three kinds, and each gets a declarative rule
//! rather than bespoke code:
//!
//!   * components that serialize a whole map, including untouched entries
//!     (tutorial progress, inlay-hint tables);
//!   * values the IDE set for itself rather than for the user (registry keys
//!     carrying `source="SYSTEM"` or `"MANAGER"`, one-shot migration flags);
//!   * components that persist only a schema version and no settings;
//!   * dialog state the platform files alongside real settings, which is what
//!     `project.default.xml` needs before it can be shared at all.
//!
//! Rules are data, so covering a newly noisy component is a table entry here
//! or an `[[xml.omit]]` block in `sync.toml` — never a new code path.

use crate::{
    config::XmlOmitRule, settings::defaults::ProductDefaults, xml::dom::Element, xml::project,
};

/// Attributes that describe the file format rather than a user's choice. A
/// component carrying only these, with no children, holds no settings.
const BOOKKEEPING_ATTRIBUTES: [&str; 2] = ["name", "version"];

struct Builtin {
    file: &'static str,
    component: Option<&'static str>,
    element: &'static str,
    attribute: &'static str,
    equals: &'static str,
    reason: &'static str,
}

/// Values written by the IDE for its own purposes. Registry keys record where
/// they came from; anything not attributable to the user is not a setting we
/// want to carry between machines.
const BUILTINS: &[Builtin] = &[
    Builtin {
        file: "options/ide.general.xml",
        component: Some("Registry"),
        element: "entry",
        attribute: "source",
        equals: "SYSTEM",
        reason: "registry key set by the IDE, not the user",
    },
    Builtin {
        file: "options/ide.general.xml",
        component: Some("Registry"),
        element: "entry",
        attribute: "source",
        equals: "MANAGER",
        reason: "registry key managed centrally, not by the user",
    },
    Builtin {
        file: "options/ide-features-trainer.xml",
        component: Some("LessonStateBase"),
        element: "entry",
        attribute: "value",
        equals: "NOT_PASSED",
        reason: "tutorial never started",
    },
    Builtin {
        file: "options/*.xml",
        component: None,
        element: "option",
        attribute: "name",
        equals: "MIGRATE_OLD_SETTINGS",
        reason: "one-shot settings migration flag",
    },
    Builtin {
        file: "options/other.xml",
        component: Some("LangManager"),
        element: "entry",
        attribute: "key",
        equals: "JAVA",
        reason: "per-installation language state",
    },
];

/// Content that is machine-local rather than merely not-a-choice, which is why
/// these run whatever `xml.use_defaults` says.
///
/// Turning that setting off widens what counts as a user choice — it keeps
/// registry keys and tutorial progress. That is not a reason to start
/// publishing another machine's window positions, and `project.default.xml` is
/// only in the manifest at all because these rules can take this content out of
/// it. Gating them on the same flag would mean a single unrelated preference
/// silently turned the exception into a leak.
///
/// `project.default.xml` is the template every new project starts from, so most
/// of it is a genuine choice — but the platform stores dialog state in the same
/// file. These four are the ones that appear there, identical across IntelliJ
/// IDEA, PyCharm, CLion, RustRover and WebStorm. Each is dropped as a whole
/// component: none of them has a leaf worth keeping, and matching the component
/// is what makes the rule survive JetBrains adding another field to it.
const ALWAYS: &[Builtin] = &[
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "WindowStateProjectService",
        reason: "dialog geometry, in this machine's screen coordinates",
    },
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "masterDetails",
        reason: "splitter positions in the settings dialog",
    },
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "ProjectInspectionProfilesVisibleTreeState",
        reason: "which inspection tree nodes were left expanded",
    },
    // One `#text` leaf holding a whole JSON document. Everything here —
    // pruning, merging, reporting, conflict resolution — addresses XML leaves,
    // so nothing inside that blob can be reached without a second
    // implementation of all four. That is the same objection that keeps
    // `llm.*.xml` out of the manifest.
    //
    // This one is not free, and the cost is worth naming: the blob mixes real
    // choices (`rearrange.code.on.save`, the third checkbox in Actions on Save,
    // whose two siblings *are* synced above) with pure dialog state
    // (`settings.editor.selected.configurable`, which changes every time you
    // open a different settings page) and with keys that hold absolute paths on
    // machines where the package was not auto-detected. Filtering by key would
    // still leave one unmergeable leaf, and would have to choose between
    // leaking those paths and silently dropping keys JetBrains adds later.
    // Sharing settings this file *can* represent beats sharing none of it; if
    // per-key handling is ever worth building, it belongs in its own change.
    Builtin {
        file: "options/project.default.xml",
        component: None,
        element: "component",
        attribute: "name",
        equals: "PropertiesComponent",
        reason: "opaque JSON blob of UI state and machine-local paths",
    },
];

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Removal {
    /// Human-readable address, as shown in reports.
    pub path: String,
    pub reason: String,
}

#[derive(Debug, Clone, Default)]
pub struct PruneOutcome {
    pub removed: Vec<Removal>,
    /// True when nothing worth storing survived, so the file itself can be
    /// dropped from the store.
    pub is_empty: bool,
}

fn file_matches(pattern: &str, relative: &str) -> bool {
    globset::Glob::new(pattern).is_ok_and(|glob| glob.compile_matcher().is_match(relative))
}

/// True when `element` is one the rule targets, given the component it sits in.
fn rule_matches(
    element: &Element,
    component: Option<&str>,
    rule_component: Option<&str>,
    rule_element: &str,
    attribute: Option<&str>,
    option: Option<&str>,
    equals: &str,
) -> bool {
    if element.name != rule_element {
        return false;
    }
    if let Some(wanted) = rule_component
        && component != Some(wanted)
        let store = staging.read(&store_file);
        let base_file = self.base_path(ide, relative);
        let base = staging.read(&base_file);

        // The file is present but holds nothing worth sharing — every setting in
        // it was pruned as a default. That is "no opinion", not "deleted", and
        // conflating the two makes two IDEs fight: one keeps contributing the
        // file and the other keeps withdrawing it.
        //
        // Standing in the base says exactly "no opinion": this IDE withdraws
        // nothing, and still adopts whatever the store has. Skipping the file
        // outright would say it twice over, because an IDE whose copy is all
        // residue could then never *receive* either. That is the common case
        // for `project.default.xml` — plenty of IDEs have dialog geometry in
        // theirs and nothing else — and it is exactly the machine that most
        // needs the settings for new projects to arrive.
        let local_view = if raw.is_some() && local_view.is_none() {
            base.clone()
        } else {
            local_view
        };

        // No special case for first contact. With no base, any setting the IDE
        // does not define is taken from the store, so a newly installed IDE
        // still adopts everything; only a setting both sides define differently
        // is a conflict, and there the default of keeping the local value means
        // a sync never silently discards what an IDE already had.
        let merged = merge::merge_file(
            base.as_deref(),
            local_view.as_deref(),
            store.as_deref(),
            options.policy,
        );

        // Record what this IDE and the store agreed on even when nothing
        // changed. Without that snapshot the next divergence has no common
        // ancestor, so a setting only one side later edits looks like a
        // conflict rather than a plain update.
        if base.as_deref() != merged.content.as_deref() {
            staging.write(&base_file, merged.content.as_deref())?;
        }

        if merged.is_noop() && removed.is_empty() {
            return Ok(None);
        }

        staging.write(&store_file, merged.content.as_deref())?;
        if !options.collect_only {
            self.write_back(
                &WriteBack {
                    ide,
                    relative,
                    ide_file: &ide_file,
                    raw: raw.as_deref(),
                    merged: &merged,
                    stamp,
                },
                staging,
            )?;
        }

        Ok(Some(FileReport {
            path: relative.to_string(),
            incoming: merged.incoming,
            outgoing: merged.outgoing,
            conflicts: merged.conflicts,
            pruned: removed,
        }))
    }

    /// Applies the incoming settings to the IDE's own file.
    ///
    /// For XML this edits individual leaves rather than overwriting, so
    /// everything pruning removed from the store view — registry keys the IDE
    /// owns, tutorial progress, migration flags — survives untouched.
    fn write_back(&self, target: &WriteBack<'_>, staging: &mut Staging) -> Result<()> {
        let WriteBack {
            ide,
            relative,
            ide_file,
            raw,
            merged,
            stamp,
        } = *target;
        if merged.incoming.is_empty() {
            return Ok(());
        }
        let Some(content) = &merged.content else {
            // The setting file went away everywhere; leave the IDE's copy alone
            // rather than deleting a file we may not fully own.
            return Ok(());
        };

//! What a product's settings look like before anyone has touched them.
//!
//! A JetBrains installer creates the config directory and fills `options/` with
//! the product's factory defaults *before* the IDE has ever run. That directory
//! is the cleanest possible answer to "did the user choose this, or did it come
//! with the product?" — and it exists only in the window between installing an
//! IDE and opening it for the first time.
//!
//! So jbsync captures it when it sees it. A never-launched IDE takes no part in
//! the sync, but its files are projected into `defaults/<Product>.toml` in the
//! store, where they replicate to every machine. Afterwards, any setting whose
//! value still equals the recorded default is treated as not-a-choice and kept
//! out of the shared store.
//!
//! This is the same judgement the platform already makes for itself — when a
//! component's state equals its default-constructed state, nothing is written
//! at all. Capturing the defaults extends that to the components which write
//! themselves out regardless.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::error::{JbsyncError, Result};

/// Where a product's defaults live inside the store.
#[must_use]
pub fn relative_path(product: &str) -> String {
    format!("defaults/{}.toml", sanitize(product))
}

/// Products come from directory names, so keep them to something filename-safe.
fn sanitize(product: &str) -> String {
    let cleaned: String = product
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-') {
                ch
            } else {
                '-'
            }
        })
        .collect();
    let trimmed = cleaned.trim_matches('-').to_string();
    if trimmed.is_empty() {
        "product".to_string()
    } else {
        trimmed
    }
}

#[derive(Debug, Clone, Default, Deserialize, Serialize)]
#[serde(default)]
pub struct ProductDefaults {
    pub version: u32,
    pub product: String,
    /// Build the capture came from, for diagnosis. Not used for matching: a
    /// value that was this product's default at any point is not evidence of a
    /// choice, and refusing to match across builds would make the capture
    /// useless the first time the IDE updated.
    pub build: String,
    /// Store-relative file path -> setting address -> default value.
    pub files: BTreeMap<String, BTreeMap<String, String>>,
}

impl ProductDefaults {
    pub fn new(product: &str, build: &str) -> Self {
        Self {
            version: 1,
            product: product.to_string(),
            build: build.to_string(),
            files: BTreeMap::new(),
        }
    }

    pub fn parse(text: &str) -> Result<Self> {
        toml::from_str(text)
            .map_err(|error| JbsyncError::configuration(format!("defaults: {error}")))
    }

    pub fn encode(&self) -> Result<String> {
        toml::to_string_pretty(self).map_err(|error| JbsyncError::configuration(error.to_string()))
    }

    /// Records one file's projected defaults, replacing any earlier capture of
    /// that file. Returns whether anything changed.
    pub fn record(&mut self, relative: &str, values: BTreeMap<String, String>) -> bool {
        if values.is_empty() {
            return false;
        }
        if self.files.get(relative) == Some(&values) {
            return false;
        }
        self.files.insert(relative.to_string(), values);
        true
    }

    /// The default value of one setting, if this product has a recorded one.
    #[must_use]
    pub fn value(&self, relative: &str, address: &str) -> Option<&str> {
        self.files.get(relative)?.get(address).map(String::as_str)
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {

