pub fn parse(a: A, input: []const u8) !*Node {
    if (!std.unicode.utf8ValidateSlice(input)) return error.InvalidXml;
    for (input) |ch| if (ch < 0x20 and ch != '\t' and ch != '\n' and ch != '\r') return error.InvalidXml;
