fn walk_relative(root: &Path) -> Vec<String> {
    const SKIP: [&str; 8] = [
        "plugins",
        "workspace",
        "system",
        "log",
        "event-log-metadata",
        "settingsSync",
        "tasks",
        "extensions",
    ];
