const A = std.mem.Allocator;
pub const Options = struct {
    dry_run: bool = false,
    policy: merge.Policy = .local,
    only: []const []const u8 = &.{},
    collect_only: bool = false,
    install_plugins: bool = true,
    message: []const u8 = "Sync JetBrains settings",
};
pub const Report = struct {
    incoming: usize = 0,
    outgoing: usize = 0,
    conflicts: usize = 0,
    pruned: usize = 0,
    details: std.Io.Writer.Allocating,
    pub fn init(a: A) Report { return .{ .details = .init(a) }; }
    fn absorb(self: *Report, label: []const u8, r: merge.Result) !void {
        self.incoming += r.incoming.items.len; self.outgoing += r.outgoing.items.len; self.conflicts += r.conflicts.items.len;
