name: Zig rewrite experiment

on:
  pull_request:
  push:
    branches: [main]

permissions:
  contents: read

concurrency:
  group: zig-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

jobs:
  native:
    name: Zig 0.17.0 / ${{ matrix.os }}
    strategy:
      fail-fast: false
      matrix:
        os: [ubuntu-latest, macos-latest, windows-latest]
    runs-on: ${{ matrix.os }}
    steps:
      - uses: actions/checkout@v4
      - uses: mlugg/setup-zig@d1434d08867e3ee9daa34448df10607b98908d29 # v2
        with:
          version: 0.17.0
      - uses: actions/setup-python@v5
        with:
          python-version: '3.12'
      - run: zig fmt --check build.zig build.zig.zon src/main.zig src/root.zig src/zig
      - run: zig build test --summary all
      - run: zig build -Doptimize=ReleaseSafe
      - name: CLI and Git scenarios
        shell: bash
        run: |
          binary=zig-out/bin/jbsync
          if [[ "$RUNNER_OS" == Windows ]]; then binary+=.exe; fi
          python tests/zig/integration.py "$binary"
      - name: Upload experimental binary
        uses: actions/upload-artifact@v4
        with:
          name: jbsync-zig-${{ matrix.os }}
          path: zig-out/bin/*

  cross:
    runs-on: ubuntu-latest
    strategy:
      fail-fast: false
      matrix:
        target: [aarch64-linux-musl, x86_64-linux-musl, aarch64-macos, x86_64-macos, x86_64-windows]
    steps:
      - uses: actions/checkout@v4
      - uses: mlugg/setup-zig@d1434d08867e3ee9daa34448df10607b98908d29 # v2
        with:
          version: 0.17.0
      - run: zig build -Dtarget=${{ matrix.target }} -Doptimize=ReleaseSafe
name: CI

on:
  pull_request:
  push:
    branches: [main]

concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.number || github.ref }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  shared:
    uses: cdenihan/rust-cli-toolkit/.github/workflows/rust-ci.yml@v2.0.0
    with:
      binary-name: jbsync
      display-name: jbsync
      environment-prefix: JBSYNC
    secrets:
      dependency_token: ${{ secrets.RUST_CLI_TOOLKIT_TOKEN }}
name: Prepare Release

on:
  push:
    branches: [main]

permissions:
  actions: write
  contents: write

concurrency:
  group: prepare-release-main
  cancel-in-progress: false

jobs:
  prepare:
    uses: cdenihan/rust-cli-toolkit/.github/workflows/prepare-release.yml@v2.0.0
    with:
      binary-name: jbsync
      display-name: jbsync
      cargo-package: jbsync
      environment-prefix: JBSYNC
      version-mode: calendar
      version-file: VERSION
      publish-workflow: publish-release.yml
    secrets:
      dependency_token: ${{ secrets.RUST_CLI_TOOLKIT_TOKEN }}
name: Release

on:
  workflow_dispatch:
    inputs:
      version:
        description: Public jbsync release version
        required: true
        type: string
      tag:
        description: Reserved Git tag
        required: true
        type: string
      commit:
        description: Bot-authored release commit
        required: true
        type: string

permissions:
  contents: write

concurrency:
  group: publish-${{ inputs.tag }}
  cancel-in-progress: false

jobs:
  publish:
    uses: cdenihan/rust-cli-toolkit/.github/workflows/publish-release.yml@v2.0.0
    with:
      version: ${{ inputs.version }}
      tag: ${{ inputs.tag }}
      commit: ${{ inputs.commit }}
      binary-name: jbsync
      display-name: jbsync
      cargo-package: jbsync
      environment-prefix: JBSYNC
    secrets:
      dependency_token: ${{ secrets.RUST_CLI_TOOLKIT_TOKEN }}
const std = @import("std");

pub fn build(b: *std.Build) void {
    if (@import("builtin").zig_version.major != 0 or @import("builtin").zig_version.minor != 17)
        @compileError("This experiment requires Zig 0.17.x");
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.addModule("jbsync", .{
        .root_source_file = b.path("src/root.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{
        .name = "jbsync",
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/main.zig"),
            .target = target,
            .optimize = optimize,
            .imports = &.{
                .{ .name = "jbsync", .module = mod },
            },
        }),
    });

    const options = b.addOptions();
    options.addOption([]const u8, "version", std.mem.trim(u8, @embedFile("VERSION"), "\r\n "));
    mod.addOptions("build_options", options);
    b.installArtifact(exe);

    const run_step = b.step("run", "Run the app");

    const run_cmd = b.addRunArtifact(exe);
    run_step.dependOn(&run_cmd.step);

    run_cmd.step.dependOn(b.getInstallStep());

    run_cmd.addPassthruArgs();

    const mod_tests = b.addTest(.{
        .root_module = mod,
    });

    const run_mod_tests = b.addRunArtifact(mod_tests);

    const exe_tests = b.addTest(.{
        .root_module = exe.root_module,
    });

    const run_exe_tests = b.addRunArtifact(exe_tests);

    const test_step = b.step("test", "Run tests");
    test_step.dependOn(&run_mod_tests.step);
    test_step.dependOn(&run_exe_tests.step);
}
