        for (ordered, 0..) |p, index| {
            if (planned[index] or caps.contains(p.id)) continue;
            if (try compatible(a, p, ide, &caps, c)) |reason| try out.print("{s}: skip {s} ({s})\n", .{ ide.name, p.id, reason });
