        self.assertIn('remote', (m.app / 'config.toml').read_text())
        (m.app / 'data').mkdir()
        (m.app / 'data/sync.toml').write_text("[jetbrains]\nbackups='false'\n")
        m.sync(expected=1)


    def test_builtin_sync_switches_and_unknown_flags(self):
        m = self.machine()
