name: Reusable Rust CLI CI

on:
  workflow_call:
    inputs:
      binary-name:
        required: true
        type: string
      display-name:
        required: true
        type: string
      environment-prefix:
        required: true
        type: string
      run-installer-tests:
        required: false
        default: true
        type: boolean
    secrets:
      dependency_token:
        required: false

permissions:
  contents: read

jobs:
  quality:
    name: Quality
    runs-on: ubuntu-latest
    timeout-minutes: 20
    env:
      DEPENDENCY_TOKEN: ${{ secrets.dependency_token }}
    steps:
      - uses: actions/checkout@v7.0.1
      - name: Authenticate private Cargo dependencies
        if: env.DEPENDENCY_TOKEN != ''
        run: git config --global url."REDACTED".insteadOf "https://github.com/"
      - uses: dtolnay/rust-toolchain@stable
        with:
          components: clippy,rustfmt
      - uses: Swatinem/rust-cache@v2.9.1
        with:
          prefix-key: v1-rust
          shared-key: ci-${{ github.repository_id }}-quality
          key: ${{ runner.os }}
          cache-bin: false
          cache-on-failure: false
          save-if: ${{ github.event_name == 'push' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch) }}
      - run: cargo fmt --all -- --check
      - run: cargo clippy --locked --all-targets --all-features -- -D warnings
      - run: cargo test --locked --all-targets
      - name: Remove private dependency credential
        if: always() && env.DEPENDENCY_TOKEN != ''
        run: git config --global --unset-all url."REDACTED".insteadOf || true

  security:
    name: RustSec audit
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - uses: actions/checkout@v7.0.1
      - uses: rustsec/audit-check@v2.0.0
        with:
          token: ${{ secrets.GITHUB_TOKEN }}

  native:
    name: Test (${{ matrix.os }})
    strategy:
