name: Reusable Rust CLI CI

on:
  workflow_call:
    inputs:
      binary-name:
        required: true
        type: string
      display-name:
        required: true
        type: string
      environment-prefix:
        required: true
        type: string
      run-installer-tests:
        required: false
        default: true
        type: boolean
    secrets:
      dependency_token:
        required: false

permissions:
  contents: read

jobs:
  quality:
    name: Quality
    runs-on: ubuntu-latest
    timeout-minutes: 20
    env:
      DEPENDENCY_TOKEN: ${{ secrets.dependency_token }}
    steps:
      - uses: actions/checkout@v7.0.1
      - name: Authenticate private Cargo dependencies
        if: env.DEPENDENCY_TOKEN != ''
        run: git config --global url."REDACTED".insteadOf "https://github.com/"
      - uses: dtolnay/rust-toolchain@stable
        with:
          components: clippy,rustfmt
      - uses: Swatinem/rust-cache@v2.9.1
        with:
          prefix-key: v1-rust
          shared-key: ci-${{ github.repository_id }}-quality
          key: ${{ runner.os }}
          cache-bin: false
          cache-on-failure: false
          save-if: ${{ github.event_name == 'push' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch) }}
      - run: cargo fmt --all -- --check
      - run: cargo clippy --locked --all-targets --all-features -- -D warnings
      - run: cargo test --locked --all-targets
      - name: Remove private dependency credential
        if: always() && env.DEPENDENCY_TOKEN != ''
        run: git config --global --unset-all url."REDACTED".insteadOf || true

  security:
    name: RustSec audit
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - uses: actions/checkout@v7.0.1
      - uses: rustsec/audit-check@v2.0.0
        with:
          token: ${{ secrets.GITHUB_TOKEN }}

  native:
    name: Test (${{ matrix.os }})
    strategy:
      fail-fast: false
      matrix:
        os: [macos-latest, windows-latest]
    runs-on: ${{ matrix.os }}
    timeout-minutes: 20
    env:
      DEPENDENCY_TOKEN: ${{ secrets.dependency_token }}
    steps:
      - uses: actions/checkout@v7.0.1
      - name: Authenticate private Cargo dependencies
        if: env.DEPENDENCY_TOKEN != ''
        shell: bash
        run: git config --global url."REDACTED".insteadOf "https://github.com/"
      - uses: dtolnay/rust-toolchain@stable
      - uses: Swatinem/rust-cache@v2.9.1
        with:
          prefix-key: v1-rust
          shared-key: ci-${{ github.repository_id }}-native
          key: ${{ runner.os }}
          cache-bin: false
          cache-on-failure: false
          save-if: ${{ github.event_name == 'push' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch) }}
      - run: cargo test --locked --all-targets
      - name: Remove private dependency credential
        if: always() && env.DEPENDENCY_TOKEN != ''
        shell: bash
        run: git config --global --unset-all url."REDACTED".insteadOf || true

  installers:
    if: inputs.run-installer-tests
    name: Installer rendering (${{ matrix.os }})
    strategy:
      fail-fast: false
      matrix:
        os: [ubuntu-latest, macos-latest, windows-latest]
    runs-on: ${{ matrix.os }}
    timeout-minutes: 10
    steps:
      - uses: cdenihan/rust-cli-toolkit/actions/render-installers@v2.0.0
        with:
          binary-name: ${{ inputs.binary-name }}
          display-name: ${{ inputs.display-name }}
          repository: ${{ github.repository }}
          environment-prefix: ${{ inputs.environment-prefix }}
          output-directory: ${{ runner.temp }}/installers
      - name: Validate POSIX installer
        if: runner.os != 'Windows'
        shell: sh
        run: |
          sh -n "$RUNNER_TEMP/installers/install.sh"
          RUST_CLI_TOOLKIT_INSTALLER_SOURCE_ONLY=1
          export RUST_CLI_TOOLKIT_INSTALLER_SOURCE_ONLY
          . "$RUNNER_TEMP/installers/install.sh"
          test "$PROGRAM" = '${{ inputs.binary-name }}'
          test "$ENV_PREFIX" = '${{ inputs.environment-prefix }}'
          test "$(artifact_for Linux x86_64 gnu)" = '${{ inputs.binary-name }}-linux-x86_64'
      - name: Validate PowerShell installer
        if: runner.os == 'Windows'
        shell: pwsh
        env:
          RENDERED_INSTALLER: ${{ runner.temp }}/installers/install.ps1
        run: |
          $sourceOnly = '${{ inputs.environment-prefix }}_INSTALLER_SOURCE_ONLY'
          [Environment]::SetEnvironmentVariable($sourceOnly, '1')
          . $env:RENDERED_INSTALLER
          if ((Get-CliArtifact 'AMD64') -ne '${{ inputs.binary-name }}-windows-x86_64.exe') { throw 'x86_64 artifact mismatch' }
          if ((Get-CliArtifact 'ARM64') -ne '${{ inputs.binary-name }}-windows-aarch64.exe') { throw 'ARM64 artifact mismatch' }

  cross-check:
    name: Check ${{ matrix.target }}
    strategy:
      fail-fast: false
      matrix:
        target:
          - x86_64-unknown-linux-musl
          - aarch64-unknown-linux-gnu
          - aarch64-unknown-linux-musl
          - x86_64-pc-windows-msvc
          - aarch64-pc-windows-msvc
          - x86_64-apple-darwin
          - aarch64-apple-darwin
    runs-on: ubuntu-latest
    timeout-minutes: 20
    env:
      DEPENDENCY_TOKEN: ${{ secrets.dependency_token }}
    steps:
      - uses: actions/checkout@v7.0.1
      - name: Authenticate private Cargo dependencies
        if: env.DEPENDENCY_TOKEN != ''
        run: git config --global url."REDACTED".insteadOf "https://github.com/"
      - uses: dtolnay/rust-toolchain@stable
        with:
          targets: ${{ matrix.target }}
      - uses: Swatinem/rust-cache@v2.9.1
        with:
          prefix-key: v1-rust
          shared-key: ci-${{ github.repository_id }}-cross-check-${{ matrix.target }}
          cache-bin: false
          cache-on-failure: false
          save-if: ${{ github.event_name == 'push' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch) }}
      - run: cargo check --locked --target ${{ matrix.target }}
      - name: Remove private dependency credential
        if: always() && env.DEPENDENCY_TOKEN != ''
        run: git config --global --unset-all url."REDACTED".insteadOf || true
name: Reusable Publish Release

on:
  workflow_call:
    inputs:
      version: { required: true, type: string }
      tag: { required: true, type: string }
      commit: { required: true, type: string }
      binary-name: { required: true, type: string }
      display-name: { required: true, type: string }
      cargo-package: { required: true, type: string }
      environment-prefix: { required: true, type: string }
    secrets:
      dependency_token:
        required: false

permissions:
  contents: write

jobs:
  verify-release:
    name: Verify trusted release inputs
    runs-on: ubuntu-latest
    outputs:
      cache-write: ${{ steps.verify.outputs.cache-write }}
    steps:
      - uses: actions/checkout@v7.0.1
        with:
          ref: ${{ inputs.commit }}
          fetch-depth: 0
      - name: Verify tag, version, commit, and dispatch ref
        id: verify
        env:
          GH_TOKEN: ${{ github.token }}
          RELEASE_COMMIT: ${{ inputs.commit }}
          RELEASE_TAG: ${{ inputs.tag }}
          RELEASE_VERSION: ${{ inputs.version }}
        shell: bash
        run: |
          [[ "$GITHUB_EVENT_NAME" == workflow_dispatch ]]
          default_branch="$(gh api "repos/${GITHUB_REPOSITORY}" --jq '.default_branch')"
          [[ "$GITHUB_REF" == "refs/heads/${default_branch}" ]]
          [[ "$RELEASE_TAG" == "v${RELEASE_VERSION}" ]]
          tagged_commit="$(gh api "repos/${GITHUB_REPOSITORY}/git/ref/tags/${RELEASE_TAG}" --jq '.object.sha')"
          [[ "$tagged_commit" == "$RELEASE_COMMIT" ]]
          git fetch origin "$default_branch"
          git merge-base --is-ancestor "$RELEASE_COMMIT" "origin/${default_branch}"
          echo 'cache-write=true' >> "$GITHUB_OUTPUT"

  build:
    name: Build ${{ matrix.target }}
    needs: verify-release
    env:
      DEPENDENCY_TOKEN: ${{ secrets.dependency_token }}
    strategy:
      fail-fast: false
      matrix:
        include:
          - { os: ubuntu-latest, target: x86_64-unknown-linux-gnu, suffix: linux-x86_64 }
          - { os: ubuntu-latest, target: x86_64-unknown-linux-musl, suffix: linux-x86_64-musl }
