name: Prepare Release

on:
  push:
    branches: [main]

permissions:
  actions: write
  contents: write

concurrency:
  group: prepare-release-main
  cancel-in-progress: false

jobs:
  prepare:
    uses: cdenihan/rust-cli-toolkit/.github/workflows/prepare-release.yml@v2.0.0
    with:
      binary-name: jbsync
      display-name: jbsync
      cargo-package: jbsync
      environment-prefix: JBSYNC
      version-mode: calendar
      version-file: VERSION
      publish-workflow: publish-release.yml
    secrets:
      dependency_token: ${{ secrets.RUST_CLI_TOOLKIT_TOKEN }}
      - uses: actions/upload-artifact@v7.0.1
        with:
          name: ${{ inputs.binary-name }}-${{ matrix.suffix }}
          path: dist/*
          if-no-files-found: error
      - name: Remove private dependency credential
        if: always() && env.DEPENDENCY_TOKEN != ''
        shell: bash
        run: git config --global --unset-all url."REDACTED".insteadOf || true

  publish:
    name: Publish GitHub release
    needs: build
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v7.0.1
        with:
          ref: ${{ inputs.commit }}
      - uses: actions/download-artifact@v8.0.1
        with:
          path: dist
          merge-multiple: true
      - uses: cdenihan/rust-cli-toolkit/actions/render-installers@v2.0.0
        with:
          binary-name: ${{ inputs.binary-name }}
          display-name: ${{ inputs.display-name }}
          repository: ${{ github.repository }}
          environment-prefix: ${{ inputs.environment-prefix }}
          output-directory: dist
      - name: Add installer checksums
        shell: bash
        run: |
          printf '%s\n' '${{ inputs.version }}' > dist/VERSION
          chmod 0755 dist/install.sh
          (cd dist && openssl dgst -sha256 -r VERSION > VERSION.sha256)
          (cd dist && openssl dgst -sha256 -r install.sh > install.sh.sha256)
          (cd dist && openssl dgst -sha256 -r install.ps1 > install.ps1.sha256)
      - name: Publish release
        env:
          GH_TOKEN: ${{ github.token }}
          RELEASE_COMMIT: ${{ inputs.commit }}
          RELEASE_TAG: ${{ inputs.tag }}
          RELEASE_VERSION: ${{ inputs.version }}
        shell: bash
        run: |
          tagged_commit="$(gh api "repos/${GITHUB_REPOSITORY}/git/ref/tags/${RELEASE_TAG}" --jq '.object.sha')"
          [[ "$tagged_commit" == "$RELEASE_COMMIT" ]] || {
            echo "Expected $RELEASE_TAG at $RELEASE_COMMIT, got $tagged_commit" >&2
            exit 1
          }
          gh release create "$RELEASE_TAG" dist/* --verify-tag \
            --title "${{ inputs.display-name }} $RELEASE_VERSION" --generate-notes

  cleanup_failed_tag:
    name: Clean up failed release reservation
    if: ${{ always() && needs.publish.result != 'success' }}
    needs: [build, publish]
    runs-on: ubuntu-latest
    steps:
      - name: Delete this run's unused reserved tag
        env:
          GH_TOKEN: ${{ github.token }}
          RELEASE_COMMIT: ${{ inputs.commit }}
          RELEASE_TAG: ${{ inputs.tag }}
        shell: bash
        run: |
          gh release view "$RELEASE_TAG" >/dev/null 2>&1 && exit 0
          reserved_sha="$(gh api "repos/${GITHUB_REPOSITORY}/git/ref/tags/${RELEASE_TAG}" --jq '.object.sha' 2>/dev/null || true)"
          [[ "$reserved_sha" != "$RELEASE_COMMIT" ]] ||
            gh api --method DELETE "repos/${GITHUB_REPOSITORY}/git/refs/tags/${RELEASE_TAG}"
fn main() -> anyhow::Result<()> {
    jbsync::cli::run()
}
//! Small ordered XML DOM for JetBrains' settings dialect. No global allocator.
//! The caller owns the arena holding nodes, decoded strings and projections.
const std = @import("std");
const A = std.mem.Allocator;
const eq = std.mem.eql;
pub const View = std.StringHashMapUnmanaged([]const u8);
const keys = [_][]const u8{ "name", "key", "id", "class", "type", "language", "scheme", "ext", "pattern" };
pub const Node = struct {
    name: []const u8,
    attrs: View = .empty,
    children: std.ArrayList(*Node) = .empty,
    text: ?[]const u8 = null,
    pub fn create(a: A, name: []const u8) !*Node {
        const n = try a.create(Node);
        n.* = .{ .name = name };
        return n;
    }
    pub fn key(self: *const Node) ?[]const u8 {
        for (keys) |k| if (self.attrs.contains(k)) return k;
        return null;
    }
    pub fn shell(self: *const Node, a: A) !*Node {
        const n = try create(a, self.name);
        var it = self.attrs.iterator();
        while (it.next()) |entry| try n.attrs.put(a, entry.key_ptr.*, entry.value_ptr.*);
        return n;
    }
    pub fn clone(self: *const Node, a: A) A.Error!*Node {
        const n = try self.shell(a);
        n.text = self.text;
        for (self.children.items) |child| try n.children.append(a, try child.clone(a));
        return n;
    }
    pub fn empty(self: *const Node) bool {
        if (self.children.items.len != 0 or self.text != null) return false;
        if (self.attrs.count() == 0) return true;
        if (eq(u8, self.name, "component")) {
            var it = self.attrs.keyIterator();
            while (it.next()) |k| if (!eq(u8, k.*, "name") and !eq(u8, k.*, "version")) return false;
            return true;
        }
        for ([_][]const u8{ "option", "entry", "map", "list", "set" }) |wrapper| {
            if (!eq(u8, wrapper, self.name)) continue;
            var it = self.attrs.keyIterator();
            while (it.next()) |k| {
                var is_key = false;
                for (keys) |v| {
                    if (eq(u8, v, k.*)) is_key = true;
                }
                if (!is_key) return false;
            }
            return true;
        }
        return false;
    }
};

const Parser = struct {
    a: A,
    input: []const u8,
    pos: usize = 0,
    fn starts(p: *Parser, s: []const u8) bool {
        return std.mem.startsWith(u8, p.input[p.pos..], s);
    }
    fn ws(p: *Parser) void {
        while (p.pos < p.input.len and std.ascii.isWhitespace(p.input[p.pos])) p.pos += 1;
    }
    fn take(p: *Parser, s: []const u8) !void {
